INSERT INTO `audios` VALUES ('f5f6c0ef89c34d24ac15dcb3b0deab45', 'fe-dark-dragon', 1, 'sb-ep01-s08', 'char-talis_king', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/ae74939e39a84e01b13d22763886e380.mp3', '塔利斯国王：他们是来抓马尔斯的。如果他落入帝国手中……希望就没了。', 'minimax', 'Chinese (Mandarin)_Humorous_Elder', NULL, 'completed', NULL, NULL, NULL, 1, '2026-04-20 22:17:31', '2026-04-21 00:35:26');
INSERT INTO `characters` VALUES ('char-alis_king', 'fe-dark-dragon', '阿利提亚先王', '马尔斯的父亲，阿利提亚前代国王。帝国入侵时坚守王城直至战死。他的牺牲激励了马尔斯走上复国之路。马尔斯最终在收复的王城中祭奠他。', NULL, NULL, NULL, '已故的英明君主回忆形象，中年男性的肖像画质感，金色短发梳理整齐，温和而坚定的眼神，身穿完整的王室礼甲，身后是阿利提亚国旗，神圣而哀伤的氛围，动漫风格', '仅存在于闪回和回忆中——语调庄重慈爱，对儿子的临别嘱托', 16, '{\"role\":\"deceased_motivator\",\"faction\":\"阿利提亚\",\"status\":\"阵亡（帝国入侵时）\",\"relation\":{\"son\":\"马尔斯\"}}', 1, '2026-04-16 23:03:40', '2026-04-16 23:42:29', NULL);
INSERT INTO `characters` VALUES ('char-cain', 'fe-dark-dragon', '凯因', '塔利斯的弓箭手，18岁。马尔斯早期战友之一，性格开朗热血，是队伍中的气氛担当。擅长远程支援作战。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/8a454b3d23eb46e3af1b5a40c1e9f975.png', 'chunzhen_xuedi', NULL, '年轻战士形象，棕色短发，身材精干敏捷，身穿轻便皮甲，背着弓箭袋，笑容爽朗自信，日系动漫风格', '热情直爽语速快，喜欢开玩笑但关键时刻靠得住', 5, '{\"role\":\"party_member\",\"faction\":\"塔利斯\",\"class\":\"弓箭手(Archer)\"}', 0, '2026-04-16 21:59:46', '2026-04-20 22:41:11', 'https://minimax-algeng-chat-tts.oss-cn-wulanchabu.aliyuncs.com/audio%2Feffect%2F06350f23f7cb62969d4b145c150d4992_1776671780815_9420.mp3?Expires=1776758180&OSSAccessKeyId=${OSS_ACCESS_KEY_ID}&Signature=***REDACTED***%2FbxGls%2BCLrtiFk%2BcMxHxW6jU%2Bg%3D');
INSERT INTO `characters` VALUES ('char-camus', 'fe-dark-dragon', '卡缪', '格鲁尼亚王国的名将，22岁。被誉为\"格鲁尼亚之狼\"，统领帝国最强的重骑兵军团。与马尔斯交战后败北，被饶恕后假死隐退。武艺超群且有荣誉感，是令人敬畏的对手。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/8ecf36804fb246d5a70dea2de99cad73.png', 'male-qn-badao-jingpin', NULL, '冷峻的青年将军形象，冰蓝色短发整齐向后梳，冷漠的浅色眼眸，身穿黑色格鲁尼亚重装骑士甲，手持长枪，面容俊美但毫无笑意，动漫风格', '冷漠简洁字斟句酌，军人作风不讲废话，重视荣誉和对手', 10, '{\"role\":\"honorable_rival\",\"faction\":\"格鲁尼亚\",\"class\":\"重装甲(Social Knight)\",\"fate\":\"假死隐退\"}', 0, '2026-04-16 21:59:46', '2026-04-20 15:57:11', 'https://minimax-algeng-chat-tts.oss-cn-wulanchabu.aliyuncs.com/audio%2Feffect%2F06350f4e26433ec0b420d33f1288bdac_1776671823845_6221.mp3?Expires=1776758223&OSSAccessKeyId=${OSS_ACCESS_KEY_ID}&Signature=***REDACTED***%2BMwI5%2BpMwkt5M%3D');
INSERT INTO `characters` VALUES ('char-elis', 'fe-dark-dragon', '艾莉丝', '马尔斯的姐姐，阿利提亚公主。帝国入侵后被囚禁在暗黑神殿深处，是马尔斯最终决战的重要动力之一。被马尔斯救出后姐弟重逢。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/4d80bc2c412d475cb118da1afe3196ae.png', 'female-tianmei', NULL, '温柔的公主形象（受困状态），银白色长发（与马尔斯相似）凌乱披散，苍白的脸庞但眼中仍有希望，身穿破旧的白色长裙，手腕上有镣铐的痕迹，脆弱而坚强的美，动漫风格', '虚弱但温暖，见到马尔斯时哽咽呼唤弟弟，声音颤抖但充满爱意', 17, '{\"role\":\"damsel_rescued\",\"faction\":\"阿利提亚\",\"status\":\"被囚禁→获救\",\"relation\":{\"brother\":\"马尔斯\"}}', 0, '2026-04-16 21:59:46', '2026-04-20 15:59:16', 'https://minimax-algeng-chat-tts.oss-cn-wulanchabu.aliyuncs.com/audio%2Feffect%2F06350fcaec7c4ab698538a9fcafc46ba_1776671948253_7255.mp3?Expires=1776758348&OSSAccessKeyId=${OSS_ACCESS_KEY_ID}&Signature=***REDACTED***%2BxmspU9YtR6QmHX%2BAKTI%3D');
INSERT INTO `characters` VALUES ('char-ganev', 'fe-dark-dragon', '卡涅夫', '多鲁亚帝国的黑暗祭司/法师，梅迪乌斯的代理人。在暗黑神殿主持暗黑仪式，制造暗黑魔法屏障保护梅迪乌斯。只有哥多教授的星光魔法才能破除其屏障。冷酷残忍的宗教狂热者。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/6fd41d988859465abb2edc162110d8ed.png', 'Robot_Armor', NULL, '邪恶的黑暗祭司形象，瘦高的身躯裹在黑色长袍中兜帽遮住大半张脸，只露出的皮肤苍白如纸，眼中闪烁诡异的红光，手中持镶嵌黑水晶的法杖，周围漂浮暗影粒子，阴森恐怖，动漫风格', '阴柔尖锐充满狂热信仰，视人类为献祭品，谈论暗黑之神时近乎癫狂', 14, '{\"role\":\"boss_minion\",\"faction\":\"多鲁亚帝国\",\"class\":\"黑暗祭司(Dark Bishop)\",\"ability\":\"暗黑魔法屏障\",\"defeated_by\":\"星光魔法\"}', 0, '2026-04-16 21:59:46', '2026-04-20 15:58:31', NULL);
INSERT INTO `characters` VALUES ('char-gotoh', 'fe-dark-dragon', '哥多', '龙人族的贤者长老。拥有千年智慧和强大的魔法力量，预言马尔斯将成为拯救大陆的英雄。向马尔斯传授星光魔法——唯一能破除卡涅夫暗黑屏障的法术。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/246ec600f11b42898a92a26e61c985c3.png', 'Chinese (Mandarin)_Humorous_Elder', NULL, '古老的龙人贤者形象，长长的白发和胡须，智慧深邃的眼睛（异色瞳一蓝一金），身穿绣满符文的白袍，手持发光的法杖，周身环绕微弱的光芒，神圣而庄严，动漫风格', '缓慢深沉充满哲理，说话像吟诵预言，语气中带着千年的沧桑', 12, '{\"role\":\"wise_mentor\",\"faction\":\"龙人族(守序)\",\"ability\":\"传授星光魔法\",\"title\":\"龙人贤者\"}', 0, '2026-04-16 21:59:46', '2026-04-20 15:57:40', NULL);
INSERT INTO `characters` VALUES ('char-gra_king', 'fe-dark-dragon', '格拉国王', '林克之父，格拉王国的暴君。当年背叛阿卡奈亚投靠帝国换取权力，统治残暴。被亲生儿子林克刺杀——这是全剧最沉重的悲剧时刻之一。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/4fd5bb795e2e4c148269c5edf7cac63b.png', 'Chinese (Mandarin)_Humorous_Elder', NULL, '堕落的老年国王形象，花白的乱发和浓密的灰胡须，肥胖臃肿的身躯穿着华丽的金边王袍，脸上布满贪婪和暴戾，坐在铺满毛皮的王座上，昏暗烛光下的阴影扭曲，动漫风格', '暴虐贪婪声音粗哑，习惯用命令口吻说话，提到权力时两眼放光', 15, '{\"role\":\"tragic_antagonist\",\"faction\":\"格拉（帝国附庸）\",\"fate\":\"被儿子林克弑杀\",\"crime\":\"背叛阿卡奈亚\"}', 0, '2026-04-16 21:59:46', '2026-04-20 15:59:00', NULL);
INSERT INTO `characters` VALUES ('char-hardin', 'fe-dark-dragon', '哈丁', '奥利安王国王弟，20岁。马其顿围城期间坚守奥利安王城的英雄。勇猛善战、为人正直，加入义军后成为马尔斯最得力的战将之一。后期命运复杂。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/89042316e7d3497bb87520472acc4417.png', 'male-qn-badao', NULL, '英武的年轻贵族骑士形象，金棕色短发，锐利的灰色眼睛，身披奥利安王家纹饰的重甲，手持骑枪，气场强大自信，动漫风格', '豪迈自信声音洪亮，直言不讳，对马尔斯既尊重又有竞争意识', 6, '{\"role\":\"party_leader\",\"faction\":\"奥利安\",\"class\":\"骑士(Paladin)\"}', 0, '2026-04-16 21:59:46', '2026-04-20 22:41:09', 'https://minimax-algeng-chat-tts.oss-cn-wulanchabu.aliyuncs.com/audio%2Feffect%2F06354a1b5491ce4e77c88124a59c8cd3_1776686876701_7962.mp3?Expires=1776773276&OSSAccessKeyId=${OSS_ACCESS_KEY_ID}&Signature=***REDACTED***%2BdtonxKjzEY%3D');
INSERT INTO `characters` VALUES ('char-jagen', 'fe-dark-dragon', '杰刚', '塔利斯王国的老骑士，约50岁。马尔斯流亡期间的守护者和导师。忠诚可靠、经验丰富，是马尔斯最信赖的老臣。教导马尔斯战斗技巧和为君之道。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/dcb8eee21d4e44dd9a41cdcc80c7df4c.png', 'Chinese (Mandarin)_Humorous_Elder', NULL, '年长的骑士形象，灰白短发和胡须，皱纹深刻但眼神锐利，身穿磨损但保养良好的重甲，手持长枪，威严而慈祥的气质，日系动漫风格', '沉稳老练语速较慢，称呼马尔斯为\"殿下\"，忠言逆耳但充满关爱', 4, '{\"role\":\"mentor\",\"faction\":\"塔利斯\",\"class\":\"骑士(Paladin)\"}', 0, '2026-04-16 23:03:40', '2026-04-20 20:07:40', 'https://minimax-algeng-chat-tts.oss-cn-wulanchabu.aliyuncs.com/audio%2Feffect%2F06354a013a62a5b93ac58498afde15c6_1776686850894_5637.mp3?Expires=1776773250&OSSAccessKeyId=${OSS_ACCESS_KEY_ID}&Signature=***REDACTED***%3D');
INSERT INTO `characters` VALUES ('char-link', 'fe-dark-dragon', '林克', '格拉王国的王子，18岁。父亲是背叛阿卡奈亚投靠帝国的暴君，林克对父亲的罪行深感悔恨。最终选择大义灭亲杀死父亲，带领格拉军队归降义军赎罪。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/2dc490f88c5645509149e8056110b577.png', 'male-qn-jingying', NULL, '忧郁的年轻王子形象，深蓝色短发略显凌乱，深邃的黑眼睛，身穿黑色和银色相间的格拉王室铠甲，表情常带愧疚和决绝，日系动漫风格', '低沉内敛说话犹豫，背负罪恶感，决定行动后会变得异常坚决', 9, '{\"role\":\"redeemed_antihero\",\"faction\":\"格拉→义军\",\"tragic_element\":\"弑父赎罪\"}', 0, '2026-04-16 21:59:46', '2026-04-20 15:56:54', NULL);
INSERT INTO `characters` VALUES ('char-manu', 'fe-dark-dragon', '玛奴（马努）', '佩拉迪龙人岛的龙人族战士。起初对人类闯入龙人领地感到愤怒，与马尔斯冲突后认可其使命，透露了龙人族内部矛盾的情报。可化为人形和龙形。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/dbc6e092d0ec444788df85652d68c3a4.png', 'Chinese (Mandarin)_Humorous_Elder', NULL, '男，老者，神秘的非人类种族形象，银白色长发飘逸，竖立的龙瞳（金色），尖耳朵，身穿带有鳞片纹理的古老服饰，周围隐约有龙气缭绕，半人半龙的奇幻美感，动漫风格', '古奥庄重用词考究，带着古老种族的距离感和逐渐消融的戒备', 11, '{\"role\":\"dragon_ally\",\"faction\":\"龙人族(守序)\",\"ability\":\"变身龙形\"}', 0, '2026-04-16 23:03:40', '2026-04-20 15:57:33', 'https://minimax-algeng-chat-tts.oss-cn-wulanchabu.aliyuncs.com/audio%2Feffect%2F06350f61e1e23c824a2ed84dd42656f4_1776671843054_363.mp3?Expires=1776758243&OSSAccessKeyId=${OSS_ACCESS_KEY_ID}&Signature=***REDACTED***%3D');
INSERT INTO `characters` VALUES ('char-maria', 'fe-dark-dragon', '玛莉亚', '密涅瓦的妹妹，14岁。马其顿王国的第二公主，心地纯洁善良。被帝国囚禁在迪鲁城地牢中，被马尔斯救出后成为队伍中的治愈者（僧侣）。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/9f4c26ec83764dae81a81baad1248d85.png', 'female-shaonv', NULL, '清纯可爱的少女形象，粉色长发柔顺垂落，水汪汪的大眼睛，身穿白色修女袍配淡金色镶边，手中握着治疗杖，天真无邪的笑容，动漫风格', '温软胆怯说话轻声细语，对姐姐密涅瓦非常依赖，害怕战斗但愿意帮助他人', 8, '{\"role\":\"healer\",\"faction\":\"马其顿→义军\",\"class\":\"僧侣(Cleric)\",\"relation\":{\"sister\":\"密涅瓦\"}}', 0, '2026-04-16 21:59:46', '2026-04-20 15:56:49', NULL);
INSERT INTO `characters` VALUES ('char-mars', 'fe-dark-dragon', '马尔斯', '阿利提亚王国王子，16岁。父王被帝国杀害后流亡塔利斯岛三年，后率军复国。性格坚毅、富有领导力但内心善良，是唯一能使用光之圣剑法尔西昂的人（安里血统）。最终成为\"星之王\"，统一阿卡奈亚大陆。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/07c898cace394c39aca262a10dbb1766.jpeg', 'male-qn-qingse', NULL, '年轻英俊男性王子形象，银白色短发，蓝色眼眸，身穿银蓝色相间的骑士铠甲，披着深红色斗篷，手持法尔西昂光剑，气质高贵而坚毅，动漫风格，精致面部特征', '沉稳坚定有担当，对朋友温暖关怀，面对敌人时果敢决断', 1, '{\"role\":\"protagonist\",\"faction\":\"义军\",\"weapon\":\"法尔西昂(光之圣剑)\",\"bloodline\":\"安里\"}', 0, '2026-04-16 21:51:30', '2026-04-21 17:02:36', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/21/65a7d3770afb40368f129dd7ad004e92.mp3');
INSERT INTO `characters` VALUES ('char-medius', 'fe-dark-dragon', '梅迪乌斯（暗黑龙）', '最终BOSS。远古暗黑龙的化身，每隔百年复活一次企图毁灭人类文明。本体为巨大的黑暗之龙，以多鲁亚帝国为傀儡统治阿卡奈亚大陆。只有法尔西昂能将其彻底消灭——这是系列的宿命轮回核心设定。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/3365f57815db422dbb4b01527e1b7c5e.png', 'Robot_Armor', NULL, '恐怖的暗黑龙形态，巨大无比的身躯覆盖黑色鳞片，红色发光的眼睛如同深渊，口中喷吐黑暗火焰和闪电，背后展开遮天蔽日的漆黑双翼，周围空间扭曲变形，终极BOSS压迫感，动漫风格', '不需要人类语言——通过心灵感应传递毁灭意志，存在本身即是绝望和恐惧', 13, '{\"role\":\"final_boss\",\"faction\":\"暗黑势力\",\"type\":\"暗黑龙(复活)\",\"weakness\":\"法尔西昂(光之圣剑)\",\"motif\":\"百年轮回\"}', 0, '2026-04-16 23:03:40', '2026-04-20 15:58:15', 'https://minimax-algeng-chat-tts.oss-cn-wulanchabu.aliyuncs.com/audio%2Feffect%2F06350f891b0484b7c2e973a0f03527d2_1776671883240_2903.mp3?Expires=1776758283&OSSAccessKeyId=${OSS_ACCESS_KEY_ID}&Signature=%2FUEiCgpqS%2B23INCS2oDHeKSuBRM%3D');
INSERT INTO `characters` VALUES ('char-minerva', 'fe-dark-dragon', '密涅瓦', '马其顿王国的公主，19岁。被称为\"赤色龙骑兵\"的女武神，率领马其顿最强龙骑兵团。起初效忠于帝国，因不满暴政且妹妹玛莉亚被囚禁而倒戈加入义军。性格骄傲但不失正义感。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/5575a9cbd8554e6b9a8da3dcea15792a.png', 'female-yujie', NULL, '威严冷艳的女性骑士形象，紫红色长发扎成高马尾，琥珀色竖瞳，身穿红色重型龙骑甲胄，背负巨型战斧，坐骑为红色飞龙（可选），气场强大不怒自威，动漫风格', '高傲冷峻语气简短，内心柔软但对陌生人戒备，谈论妹妹时语气软化', 7, '{\"role\":\"ally_commander\",\"faction\":\"马其顿→义军\",\"class\":\"龙骑(Dragon Knight)\",\"title\":\"赤色龙骑兵\"}', 0, '2026-04-16 21:59:46', '2026-04-20 15:56:39', NULL);
INSERT INTO `characters` VALUES ('char-nina', 'fe-dark-dragon', '妮娜', '阿卡奈亚公主，17岁。阿卡奈亚亡国后的遗孤领袖，率领抵抗军坚持斗争。聪慧冷静，持有火焰纹章（王室代代相传的封印之盾）。将火焰纹章交给马尔斯后成为重要盟友，战后重建阿卡奈亚并即位女王。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/19/1013d36a492542249e21808eb1f067e4.png', 'female-chengshu', NULL, '优雅高贵的公主形象，金色长发编成复杂的辫子，蓝紫色眼眸，身穿深蓝色礼服式铠甲，肩部有阿卡奈亚纹章装饰，手持火焰纹章徽盾，气质成熟冷静，动漫风格', '端庄优雅言辞谨慎，作为公主有责任感，偶尔流露孤独和坚韧', 3, '{\"role\":\"ally_leader\",\"faction\":\"阿卡奈亚抵抗军\",\"item\":\"火焰纹章\"}', 0, '2026-04-16 21:51:30', '2026-04-20 15:55:17', 'https://minimax-algeng-chat-tts.oss-cn-wulanchabu.aliyuncs.com/audio%2Feffect%2F06350edb341f478dc1b968676ec6afa8_1776671708841_3355.mp3?Expires=1776758108&OSSAccessKeyId=${OSS_ACCESS_KEY_ID}&Signature=***REDACTED***%3D');
INSERT INTO `characters` VALUES ('char-shiida', 'fe-dark-dragon', '希达', '塔利斯公主，15岁。天真烂漫却勇敢坚强，在帝国入侵时找到马尔斯求助。对马尔斯一见倾心，是马尔斯最重要的精神支柱之一。最终成为阿利提亚王后。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/9589d23d3ca64315a7e79e1388ceb7eb.jpeg', 'diadia_xuemei', NULL, '美丽年轻的公主形象，浅绿色长发及腰，碧绿眼睛，身穿白色和淡紫色相间的长裙配银色护甲，头戴小巧的王冠，温柔而坚定的表情，动漫风格', '活泼开朗带点娇羞，关心马尔斯时会变得认真，战斗时勇敢无畏', 2, '{\"role\":\"heroine\",\"faction\":\"塔利斯\",\"relation_to_mars\":\"恋人→妻子\"}', 0, '2026-04-16 21:51:30', '2026-04-20 16:04:27', 'https://minimax-algeng-chat-tts.oss-cn-wulanchabu.aliyuncs.com/audio%2Feffect%2F06350ec4d2eabe9d5d66eacd81648864_1776671685450_9824.mp3?Expires=1776758085&OSSAccessKeyId=${OSS_ACCESS_KEY_ID}&Signature=***REDACTED***%3D');
INSERT INTO `characters` VALUES ('char-talis_king', 'fe-dark-dragon', '塔利斯国王', '希达的父亲，塔利斯岛的统治者。在帝国入侵时支持马尔斯，为其提供船只和物资开启征程。开明的明君。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/ae5059950a37427ab57fd46f87d23276.png', NULL, NULL, '和蔼的中年国王形象，棕灰色短发和修剪整齐的胡须，身穿塔利斯风格的海洋蓝色王服，坐在朴素但整洁的书房中，书架上摆满航海图，睿智温和的气质，动漫风格', '温和而有远见，说话条理清晰，对女儿希达宠溺但尊重她的选择', 18, '{\"role\":\"supporting_ally\",\"faction\":\"塔利斯\",\"action\":\"资助马尔斯出海复国\"}', 0, '2026-04-16 21:59:46', '2026-04-20 12:15:25', NULL);
INSERT INTO `characters` VALUES ('demochar001', 'demo-drama-001', '林小雨', '女主角，26岁，独立设计师。性格外冷内热，外表干练但内心柔软。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/21/5ba220ce61f2417c9c09b871550efb73.png', 'female-tianmei', NULL, '年轻亚洲女性，黑色长发微卷，穿着简约时尚的米色风衣，精致妆容，眼神温柔坚定，城市街景背景', '简洁干练偶尔流露感性', 1, NULL, 0, '2026-04-10 00:18:18', '2026-04-21 17:03:00', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/21/c97c1e3359a3479f83259008020b93e4.mp3');
INSERT INTO `characters` VALUES ('demochar002', 'demo-drama-001', '顾辰', '男主角，29岁，科技公司CEO。沉稳内敛，做事雷厉风行但对待感情笨拙。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/22/8a691046eb5648dbb3de1a3af1e0c154.png', 'male-qn-badao', NULL, '男，29岁，看起来小鲜肉，短发利落，穿深色高定西装，气质成熟稳重，眼神深邃，办公室背景英俊亚洲男性，短', '低沉冷静偶尔带一丝温柔', 2, NULL, 0, '2026-04-10 00:18:18', '2026-04-22 16:08:14', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/21/478199e7ab4a4f5ca12a5b46e5ca11f1.mp3');
INSERT INTO `characters` VALUES ('demochar003', 'demo-drama-001', '苏珊', '女配角，25岁，林小雨的闺蜜兼同事。活泼开朗，是团队的开心果。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/22/7ad8049033734f8b8d3f59605a135ec2.png', 'danya_xuejie', NULL, '25岁年轻亚洲女性，扎着马尾辫，穿休闲彩色卫衣，笑容灿烂，咖啡厅背景', '热情开朗语速较快', 3, NULL, 0, '2026-04-10 00:18:18', '2026-04-22 16:12:01', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/21/c1a5c3464154451b95c203c82a9ba466.mp3');
INSERT INTO `dramas` VALUES ('demo-drama-001', '示例短剧《都市奇缘》', '一个发生在现代都市的爱情悬疑故事，讲述三位主角在意外相遇后的命运交织。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/22/e2ad735e80f34cf8962bb846b5547c00.png', 'draft', 5, 0, NULL, 0, '2026-04-10 00:18:18', '2026-04-22 16:17:04');
INSERT INTO `dramas` VALUES ('demo-drama-002', '测试短剧《古风江湖》', '古代武侠题材的测试用例。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/16/26cc8dbb15f447f9b5fa2e2fe32a1470.png', 'draft', 3, 1, NULL, 0, '2026-04-10 00:18:18', '2026-04-16 22:06:36');
INSERT INTO `dramas` VALUES ('fe-dark-dragon', '《火焰之纹章：暗黑龙与光之剑》', '系列原点之作。阿利提亚王子马尔斯在祖国沦陷后流亡三年，从塔利斯岛起兵，联合奥利安、马其顿、格拉、格鲁尼亚等诸国义军，最终击败暗黑神梅迪乌斯，解放阿卡奈亚大陆。包含宿命轮回、神剑封印、龙人族等核心设定。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/16/1d4e4b258c0b4b82a0e501a8161b2f09.png', 'draft', 10, 0, '{\"genre\":\"奇幻/战争\",\"era\":\"中世纪幻想大陆\",\"themes\":[\"宿命与成长\",\"复国与正义\",\"友情与牺牲\"],\"core_items\":[\"火焰纹章(封印之盾)\",\"法尔西昂(光之圣剑)\",\"星光魔法\"]}', 0, '2026-04-16 21:51:30', '2026-04-20 20:12:28');
INSERT INTO `episode_exports` VALUES ('1232f58174884ed6be89de970baa9c1d', 'fe-dark-dragon', 1, 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/7dc40d3d756e4cdfb0b94e8655e8776d.mp4', 13.408, 'completed', 3, NULL, '{\"shotCount\":3,\"storyboardCount\":11,\"withAudioMerged\":true,\"composedAt\":\"2026-04-20T23:23:25.623278800\"}', 0, '2026-04-20 23:23:26', '2026-04-20 23:23:26');
