INSERT INTO `episode_exports` VALUES ('ec0794e64d0d45ae8ffefc97e9ddca1d', 'fe-dark-dragon', 1, 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/22/d0dd2454375d42c2989e9d211e5dffb4.mp4', 35.3333, 'completed', 6, NULL, '{\"shotCount\":6,\"storyboardCount\":6,\"withAudioSync\":true,\"withSubtitleRender\":true,\"composedAt\":\"2026-04-22T11:30:20.837237\",\"shotDetails\":[ {\r\n  \"storyboardId\" : \"sb-ep01-s07\",\r\n  \"strategy\" : \"FAILED_FALLBACK\",\r\n  \"error\" : \"FFmpeg PadSilence-FinalMix 失败 (退出码: -22)\",\r\n  \"shotNumber\" : 1\r\n}, {\r\n  \"storyboardId\" : \"sb-ep01-s08\",\r\n  \"strategy\" : \"FAILED_FALLBACK\",\r\n  \"error\" : \"FFmpeg DirectBlend 失败 (退出码: -22)\",\r\n  \"shotNumber\" : 2\r\n}, {\r\n  \"storyboardId\" : \"sb-ep01-s03\",\r\n  \"strategy\" : \"FAILED_FALLBACK\",\r\n  \"error\" : \"FFmpeg PadSilence-FinalMix 失败 (退出码: -22)\",\r\n  \"shotNumber\" : 3\r\n}, {\r\n  \"storyboardId\" : \"sb-ep01-s04\",\r\n  \"strategy\" : \"FAILED_FALLBACK\",\r\n  \"error\" : \"FFmpeg PadSilence-FinalMix 失败 (退出码: -22)\",\r\n  \"shotNumber\" : 4\r\n}, {\r\n  \"storyboardId\" : \"sb-ep01-s05\",\r\n  \"strategy\" : \"FAILED_FALLBACK\",\r\n  \"error\" : \"FFmpeg PadSilence-FinalMix 失败 (退出码: -22)\",\r\n  \"shotNumber\" : 5\r\n}, {\r\n  \"storyboardId\" : \"sb-ep01-s06\",\r\n  \"strategy\" : \"FAILED_FALLBACK\",\r\n  \"error\" : \"FFmpeg PadSilence-FinalMix 失败 (退出码: -22)\",\r\n  \"shotNumber\" : 6\r\n} ]}', 0, '2026-04-22 11:30:21', '2026-04-22 11:30:21');
INSERT INTO `episode_exports` VALUES ('fddabeeb7dca48139fee16927cf930d1', 'fe-dark-dragon', 1, 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/21/d1a0b2584baa4eefae562212a093a5d4.mp4', 24.6939, 'completed', 6, NULL, '{\"shotCount\":6,\"storyboardCount\":6,\"withAudioMerged\":true,\"composedAt\":\"2026-04-21T23:18:10.660824500\"}', 0, '2026-04-21 23:18:11', '2026-04-21 23:18:11');
INSERT INTO `scenes` VALUES ('1b94d944cf244feba79374ee313f7869', 'fe-dark-dragon', '11', '111', '', '11', '白天', '1111', NULL, 1, '2026-04-16 23:25:33', '2026-04-16 23:42:43');
INSERT INTO `scenes` VALUES ('altea-border', 'fe-dark-dragon', '阿利提亚边境', '马尔斯阔别三年后重返祖国土地的第一站。情感浓烈的归乡时刻。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/797f463542c74680b12c2012c51d192a.png', '阿利提亚边境', '黎明', '黎明时分的国境线，一条古道穿过起伏的丘陵通向远方阿利提亚的方向，路边的界碑上依稀可辨\"ALTEA\"的字样（已被破坏），晨雾笼罩的大地逐渐被金色的曙光穿透，充满希望与感伤交织的情绪，动漫风格', '{\"chapter\":\"第六章\",\"episodes\":[\"15\"]}', 0, '2026-04-16 21:59:46', '2026-04-20 13:46:18');
INSERT INTO `scenes` VALUES ('altea-city-wall', 'fe-dark-dragon', '阿利提亚城头（结局）', '战后重建的阿利提亚都城城头。马尔斯与希达眺望和平大陆的经典结局画面。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/2885d4ee1365451db4446c137a4dce96.png', '阿利提亚王城', '日出', '清晨阳光下的城楼顶部，石质垛口上站着两个身影（远景），前方是正在苏醒的城市——屋顶炊烟升起，街道上行人渐多，远处的田野绿意盎然，金色朝阳从东方地平线洒满整幅画面，温暖治愈的希望之光，动漫风格', '{\"chapter\":\"结局\",\"episodes\":[\"22\"],\"finale_scene\":true}', 0, '2026-04-16 23:03:40', '2026-04-20 13:43:12');
INSERT INTO `scenes` VALUES ('altea-throne-room', 'fe-dark-dragon', '阿利提亚王座大厅', '被占领后收复的阿利提亚王城主殿。马尔斯在此祭奠父王并宣告复国。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/d09c1530c81b4e44b840eaae05c51fc3.png', '阿利提亚王城', '白天', '收复后的王座大厅，阳光透过彩色玻璃穹顶洒下斑驳光影，破碎的王座已被重新修复，墙壁上残留的战斗痕迹尚未完全清理，地上摆放着鲜花和祭品——这是祭奠先王的场所，庄严肃穆中带着新生的希望，动漫风格', '{\"chapter\":\"第六章\",\"episodes\":[\"16\"]}', 0, '2026-04-16 21:59:46', '2026-04-20 13:45:43');
INSERT INTO `scenes` VALUES ('dark-shrine', 'fe-dark-dragon', '暗黑神殿', '梅迪乌斯和卡涅夫的据点。最邪恶的场所——暗黑仪式的舞台、最终BOSS战的场地。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/846d4c26d2ba465f8dab82eceb955205.png', '多鲁亚帝国核心', '永夜', '终极邪恶的殿堂，巨大的空间由黑色玄武岩构建，无数蜡烛和暗红火焰提供诡异照明，地面绘有召唤法阵（发光的暗色纹路），中央是一个升起的祭坛，上方悬挂着扭曲的空间裂缝，绝对的黑暗与恐惧氛围，动漫风格', '{\"chapter\":\"第八章\",\"episodes\":[\"20\",\"21\"],\"final_boss_location\":true}', 0, '2026-04-16 23:03:40', '2026-04-20 12:36:15');
INSERT INTO `scenes` VALUES ('deil-castle', 'fe-dark-dragon', '迪鲁城', '囚禁玛莉亚的地牢所在城堡。阴森的帝国监狱要塞。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/4c8a685001b04e0cafd3abac0f3c7750.png', '迪鲁领地', '夜晚', '阴暗的要塞城堡，黑色石墙上插满尖锐的铁刺，城门紧闭只有火把提供照明，塔楼上巡逻的士兵剪影，整体色调偏冷灰蓝色，压迫感十足的监狱氛围，动漫风格', '{\"chapter\":\"第三章\",\"episodes\":[\"9\"]}', 0, '2026-04-16 21:59:46', '2026-04-20 12:39:59');
INSERT INTO `scenes` VALUES ('deil-dungeon', 'fe-dark-dragon', '迪鲁城地牢', '玛莉亚被囚禁的地下牢房。潮湿、黑暗、绝望。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/b3b9e5bed34642399636387620eacf8a.png', '迪鲁城地下', '黑暗', '狭小阴湿的石室牢房，墙壁渗水长满青苔，地面铺着干草，角落里有一张破旧的小床，铁栅栏门上的锁锈迹斑斑，唯一的光源来自高处窄小的透气窗透入的一丝月光，绝望氛围，动漫风格', '{\"chapter\":\"第三章\",\"episodes\":[\"9\"]}', 0, '2026-04-16 21:59:46', '2026-04-20 13:37:42');
INSERT INTO `scenes` VALUES ('deil-outer', 'fe-dark-dragon', '迪鲁城外围', '迪鲁城周边的平原战场，玛莉亚被囚禁的城堡近郊。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/97f8379f8677400a8f151682d8fa7d8d.png', '迪鲁领地', '白天', '战火洗礼过的平原废墟，烧焦的土地和断裂的兵器散落各处，远处迪鲁城的高耸城墙在烟尘中若隐若现，乌云压顶的阴沉天空，肃杀的战争前奏氛围，动漫风格', '{\"chapter\":\"第三章\",\"episodes\":[\"8\"]}', 0, '2026-04-16 21:59:46', '2026-04-20 13:42:33');
INSERT INTO `scenes` VALUES ('demo-scene-001', 'demo-drama-001', '设计工作室', '林小雨工作的创意设计空间，充满艺术气息和灵感元素。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/21/972ba5df23f74888a5f58224d789e0bf.png', '上海市中心CBD写字楼', '白天', '现代化开放式办公室设计工作室，大落地窗俯瞰城市天际线，白色墙面装饰着各种设计手稿和色彩样板，暖色调灯光，ins风', NULL, 0, '2026-04-10 00:18:18', '2026-04-21 17:07:56');
INSERT INTO `scenes` VALUES ('demo-scene-002', 'demo-drama-001', '高级餐厅', '两人第一次正式约会的法式餐厅，氛围浪漫优雅。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/21/88cd48493d984742acd81929bbea9eea.png', '上海外滩', '夜晚', '高档法式餐厅内部，烛光餐桌，窗外是璀璨的城市夜景和黄浦江倒影，水晶吊灯，浪漫氛围，电影质感光效', NULL, 0, '2026-04-10 00:18:18', '2026-04-21 17:08:55');
INSERT INTO `scenes` VALUES ('demo-scene-003', 'demo-drama-001', '雨中街道', '两人在雨天意外相遇的街角，命运的开端。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/22/ce3bfc9042384a648304f7535735a607.png', '上海老城区街道', '黄昏转夜晚', '城市老街区石板路街道下着细雨，路灯昏黄温暖的光晕，湿漉漉的地面反射着霓虹灯招牌，文艺电影感构图，有人撑伞', NULL, 0, '2026-04-10 00:18:18', '2026-04-22 16:40:20');
INSERT INTO `scenes` VALUES ('dolhr-territory', 'fe-dark-dragon', '多鲁亚帝国本土', '义军攻入帝国腹地的荒原。焦土般的敌国领土。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/0734211ae8ad40daaabe98f057289b81.png', '多鲁亚帝国', '黄昏', '被战争摧毁的帝国领土，黑色的火山岩地貌，地表裂开喷出硫磺烟雾，远处有被烧毁的城镇残骸，天空呈现出不祥的暗红色，大军行进的剪影在地平线上推进，末日般苍凉的氛围，动漫风格', '{\"chapter\":\"第八章\",\"episodes\":[\"19\"]}', 0, '2026-04-16 21:59:46', '2026-04-20 12:35:03');
INSERT INTO `scenes` VALUES ('dragon-cave', 'fe-dark-dragon', '龙人洞穴', '通往岛屿内部的天然洞穴系统，钟乳石和地下河构成的危险地形。堕落地龙出没之处。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/74e28bf66cdd4c3381108dc2cf650a97.png', '龙人岛深处', '黑暗', '幽深的地下洞穴，发光的苔藓和水晶簇提供微弱照明，地面上有巨大爪痕和鳞片痕迹暗示龙的栖息，地下河发出低沉的水声，狭窄通道通向更深的未知区域，危险神秘氛围，动漫风格', '{\"chapter\":\"第二章\",\"episodes\":[\"7\"]}', 0, '2026-04-16 21:59:46', '2026-04-20 13:50:44');
INSERT INTO `scenes` VALUES ('dragon-island-entrance', 'fe-dark-dragon', '龙人岛入口', '佩拉迪龙人岛的岸边入口，奇异的植被和空气中弥漫的魔法气息。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/47053324a58247db961a2ed6afae90c8.png', '龙人岛', '黄昏', '神秘的岛屿岸边，巨大的奇异植物发出微弱的荧光，空气中有肉眼可见的魔力粒子漂浮，远处山体上有古老的龙形雕刻若隐若现，紫红色天空下的奇幻景观，神秘氛围，动漫风格', '{\"chapter\":\"第二章\",\"episodes\":[\"6\"]}', 0, '2026-04-16 21:59:46', '2026-04-20 13:50:22');
INSERT INTO `scenes` VALUES ('dragon-sanctuary', 'fe-dark-dragon', '龙人圣所', '哥多传授星光魔法的神圣空间。龙人族最隐秘的圣地。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/f697bccb5a4243ccb439583ad466cfdd.png', '龙人岛最深处', '永恒暮光', '超越凡间的奇幻圣所，没有明确的天花板——上方是无尽的星河旋涡缓缓转动，脚下是由纯粹光芒构成的平台，四周漂浮着古代龙族的雕像和卷轴，哥多的身影站在星河中心，极致的奇幻神性美感，动漫风格', '{\"chapter\":\"第七章\",\"episodes\":[\"18\"],\"magic_taught\":\"星光魔法\"}', 0, '2026-04-16 23:03:40', '2026-04-20 13:49:56');
INSERT INTO `scenes` VALUES ('gra-border', 'fe-dark-dragon', '格拉边境防线', '格拉王国设置的边境防御工事。林克的部队在此阻击义军。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/497bba35bb6c4f0b84c4fe5f03273d6a.png', '格拉王国边境', '白天', '边境军事要塞，木制拒马和壕沟组成的防线后方是格拉军队的营帐，远处可见格拉国旗（黑底金纹），天空中有侦查骑兵的尘土扬起，对峙的紧张感，动漫风格', '{\"chapter\":\"第四章\",\"episodes\":[\"11\"]}', 0, '2026-04-16 21:59:46', '2026-04-20 13:36:17');
INSERT INTO `scenes` VALUES ('gra-throne-room', 'fe-dark-dragon', '格拉王宫大殿', '暴君格拉国王的王座厅。林克弑父的悲剧发生地。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/a4746d58c3db416e9a5f72e863a1a8bc.png', '格拉王城', '夜晚', '奢华但令人窒息的王座大厅，黑色大理石柱支撑着高耸的天花板，金丝织就的地毯通向尽头的王座，两侧点燃的长明灯投下摇曳的光影，王座上的暴君身影被阴影吞噬，沉重压抑的戏剧性空间，动漫风格', '{\"chapter\":\"第四章\",\"episodes\":[\"12\"]}', 0, '2026-04-16 21:59:46', '2026-04-20 12:36:39');
INSERT INTO `scenes` VALUES ('grunia-castle', 'fe-dark-dragon', '格鲁尼亚城堡', '卡缪与马尔斯决斗的城堡大厅。格鲁尼亚的军事要塞核心。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/fd376b6a1f7a45689d0b9a16e621dbca.png', '格鲁尼亚首都', '黄昏', '坚固的军事堡垒内部，厚重的石墙上挂满了历代名将的铠甲和武器作为装饰，中央是一个圆形的决斗场区域，高处的窗户射入橙红色的夕阳余晖形成丁达尔效应，肃穆庄严的武士道氛围，动漫风格', '{\"chapter\":\"第五章\",\"episodes\":[\"14\"]}', 0, '2026-04-16 21:59:46', '2026-04-20 12:39:03');
INSERT INTO `scenes` VALUES ('grunia-plains', 'fe-dark-dragon', '格鲁尼亚平原', '卡缪率领重骑兵军团与义军交战的广阔平原。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/e09411c34353442ca652539e61303368.png', '格鲁尼亚王国', '白天', '一望无际的草原战场，草地上布满了车辙印和马蹄坑，远处地平线上黑压压的重装骑兵方阵正在推进，天空中盘旋的战鹰，史诗级战争场面的壮阔与残酷并存，动漫风格', '{\"chapter\":\"第五章\",\"episodes\":[\"13\"]}', 0, '2026-04-16 21:59:46', '2026-04-20 12:39:38');
INSERT INTO `scenes` VALUES ('kadain-shrine', 'fe-dark-dragon', '卡达因神殿', '安里王室遗留的神圣殿堂，封印着光之剑法尔西昂。古老而庄严。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/a0bc9689ec0f497e8be04788d38592e3.png', '卡达因遗迹', '正午', '古老的神殿内景，纯白色的石柱直达穹顶，地面刻满发光的神圣符文，殿堂尽头的高台上悬浮着一把散发着柔和光芒的剑（法尔西昂），整个空间充满神圣的金色光辉，超凡脱俗的神性氛围，动漫风格', '{\"chapter\":\"第七章\",\"episodes\":[\"17\"],\"sacred_item\":\"法尔西昂(光之圣剑)\"}', 0, '2026-04-16 23:03:40', '2026-04-20 12:17:50');
INSERT INTO `scenes` VALUES ('macedon-camp', 'fe-dark-dragon', '马其顿野战营地', '密涅瓦与马尔斯会面的野外营地。龙骑兵团驻扎之地。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/0d03b239b39d44258e406e735deb7ee8.png', '马其顿边境', '傍晚', '军旅野营地的景象，数顶大型军用帐篷呈环形布置，中央空地上拴着披甲的战马，远处的篝火上烤着肉食，身穿红色龙骑甲的士兵们擦拭武器或喂马，红色旗帜在风中飘扬，豪迈粗犷的氛围，动漫风格', '{\"chapter\":\"第三章\",\"episodes\":[\"10\"]}', 0, '2026-04-16 21:59:46', '2026-04-20 13:48:26');
INSERT INTO `scenes` VALUES ('scene-akaneia-resistance', 'fe-dark-dragon', '阿卡奈亚抵抗军营地', '妮娜公主领导的抵抗军秘密基地。隐藏在森林深处的临时营寨。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/be45b8c3aafd4b949b0de849adcd6644.png', '阿卡奈亚废墟周边', '夜晚', '森林中的秘密营地，多顶帆布帐篷散布在巨树之间，篝火燃烧映照着战士们疲惫的面孔，中央大帐挂着残破的阿卡奈亚国旗，周围设置了暗哨警戒，紧张而团结的氛围，动漫风格', '{\"chapter\":\"第一章\",\"episodes\":[\"5\"]}', 0, '2026-04-16 21:59:46', '2026-04-20 13:48:02');
INSERT INTO `scenes` VALUES ('scene-orlean-coast', 'fe-dark-dragon', '奥利安海岸', '奥利安王国的海滨地带，马尔斯一行登陆的地方。沙滩延伸至悬崖峭壁。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/17/ad6d04baca794c56bebc1d543e29637b.png', '奥利安王国', '清晨', '广阔的海岸线景观，金色沙滩与高耸的白垩岩崖相接，海浪拍打礁石溅起白色泡沫，远处可见奥利安王城的轮廓，晨光中的薄雾，清新开阔的氛围，动漫风格', '{\"chapter\":\"第一章\",\"episodes\":[\"3\"]}', 0, '2026-04-16 21:59:46', '2026-04-17 11:11:29');
INSERT INTO `scenes` VALUES ('scene-orlen-castle', 'fe-dark-dragon', '奥利安王城', '奥利安王国的首都城堡，被马其顿军队围困期间哈丁坚守于此。城内物资紧缺但士气尚存。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/dfad0cba15cd46a5bad70023e7e78449.png', '奥利安王国', '白天', '宏伟的中世纪王城内部庭院，石砌建筑带有奥利安蓝白纹饰旗帜，士兵们在城墙缺口处加固防御，城内平民排队领取稀少的食物，坚毅而压抑的氛围，动漫风格', '{\"chapter\":\"第一章\",\"episodes\":[\"4\"]}', 0, '2026-04-16 21:59:46', '2026-04-20 12:35:26');
INSERT INTO `scenes` VALUES ('scene-talis-castle', 'fe-dark-dragon', '塔利斯城', '塔利斯岛的主城，石墙环绕的城堡。帝国军围攻时这里成为最后的防线。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/4d3c8e4a35134896bbab5232c9374bc9.png', '塔利斯岛', '黄昏', '中世纪城堡外观，灰白色城墙在夕阳下泛着金光，城门口有守卫和村民慌乱奔跑，远处的天际线有黑烟升起暗示战斗逼近，紧张氛围，动漫风格', '{\"chapter\":\"序章\",\"episodes\":[\"2\"]}', 0, '2026-04-16 21:59:46', '2026-04-20 12:28:56');
INSERT INTO `scenes` VALUES ('scene-talis-village', 'fe-dark-dragon', '塔利斯村', '塔利斯岛的宁静渔村，马尔斯流亡三年的居所。木质房屋沿海岸排列，村民们以捕鱼为生。', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/2633a003009541a5bc333136bffa2927.png', '塔利斯岛', '白天', '中世纪幻想风格的海边小村庄，木制房屋错落排列在岩石海岸上，远处是蔚蓝的大海，几艘渔船停泊在浅湾，炊烟袅袅升起，晴朗的天气，温暖的阳光，动漫风格', '{\"chapter\":\"序章\",\"episodes\":[\"1\"]}', 0, '2026-04-16 21:59:46', '2026-04-20 12:33:04');
INSERT INTO `storyboards` VALUES ('01a8815f99a5432c9ad61d10c67a7f6b', 'demo-drama-001', 1, 2, 2, 'medium', '跟拍', '苏珊端着咖啡从旁边走近，带着笑意伸手轻轻拍了一下林小雨的肩膀', '又熬方案？出去透透气啦', 'demochar003', 'demo-scene-001', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/22/7ad8049033734f8b8d3f59605a135ec2.png', NULL, NULL, NULL, 'pending', NULL, 0, '2026-04-22 17:09:08', '2026-04-22 17:59:23');
INSERT INTO `storyboards` VALUES ('0436611fabff410897f327e45fad40ad', 'demo-drama-001', 1, 31, 47, 'wide', '俯拍拉远', '城市全景，朝阳完全升起，新的一天开始，但城市中隐藏的暗流开始涌动，本集完', '', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:37:48', '2026-04-21 00:13:07');
INSERT INTO `storyboards` VALUES ('0769b294c5d84e88840f1288a9e8c189', 'demo-drama-001', 1, 1, 1, 'medium', '固定镜头', '林小雨坐在设计工作室的桌前，眉头微蹙，认真审视着面前的设计稿，指尖轻轻划过手稿细节，侧脸在暖黄色灯光下显得柔和清冷', '', 'demochar001', 'demo-scene-001', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/21/5ba220ce61f2417c9c09b871550efb73.png', NULL, NULL, NULL, 'pending', NULL, 0, '2026-04-22 17:09:08', '2026-04-22 17:59:21');
INSERT INTO `storyboards` VALUES ('085b13f5aa0840adbe77b7485e742f77', 'demo-drama-001', 1, 4, 20, 'wide', '摇镜头', '咖啡馆门被推开，一位身着黑色风衣的年轻男子（顾言）步入店内，他摘下墨镜，环顾四周，目光最终落在窗边的林小溪身上', '', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:37:48', '2026-04-21 00:14:09');
INSERT INTO `storyboards` VALUES ('135f70ce1f83417185ddf2bf9abf89a2', 'demo-drama-001', 1, 14, 14, 'medium', '固定镜头', '餐厅角落的暗处，有一道隐秘的目光正悄悄锁定林小雨和顾辰两人的身影，将这场看似偶然的邂逅尽收眼底', '', 'demochar003', 'demo-scene-002', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/22/7ad8049033734f8b8d3f59605a135ec2.png', NULL, NULL, NULL, 'pending', NULL, 0, '2026-04-22 17:09:08', '2026-04-22 17:18:15');
INSERT INTO `storyboards` VALUES ('1959b42d1e49451a93597432062fee82', 'demo-drama-001', 1, 24, 40, 'wide', '俯拍', '城市另一端，一栋废弃的旧工厂内，神秘男子走入，身后跟着几名手下，他拿出那枚徽章放在桌上', '目标已经出现，按计划行动。', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:37:48', '2026-04-21 00:13:24');
INSERT INTO `storyboards` VALUES ('20e14bb375d44b5881034f326ba07334', 'demo-drama-001', 1, 27, 43, 'medium', '推镜头', '林小溪翻开笔记本最后一页，上面写着：\"如果有一天我消失了，替我找出真相\"——落款是顾言，日期是五年前', '', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:37:48', '2026-04-21 00:13:17');
INSERT INTO `storyboards` VALUES ('22a749dcf34c42ab9878da3faa5b7486', 'demo-drama-001', 1, 9, 9, 'close-up', '固定镜头', '林逸晨将雨伞递给苏雨桐，两人的手不经意间触碰', '不客气', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:36:31', '2026-04-21 00:14:28');
INSERT INTO `storyboards` VALUES ('235b0e11d0414f749ac6f1e92e975c7b', 'demo-drama-001', 1, 11, 11, 'medium', '固定镜头', '苏雨桐转身离开，回头看了林逸晨一眼，林逸晨也注视着她的背影', '', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:36:31', '2026-04-21 00:14:31');
INSERT INTO `storyboards` VALUES ('251ffdcad83d41ff93e3cf63e58d740b', 'demo-drama-001', 1, 8, 8, 'wide', '环绕', '林小雨、苏珊、顾辰三人出现在同一个场合，表面看似温馨和谐，但镜头捕捉到三人之间微妙的眼神交错，暗示着暗流涌动', '', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-22 16:21:52', '2026-04-22 16:44:36');
INSERT INTO `storyboards` VALUES ('2fdd0148a5d04fccb7a056024c5139a0', 'demo-drama-001', 1, 3, 3, 'wide', '固定镜头', '细雨绵绵敲打着石板路，昏黄的路灯在湿润的地面上映出温暖的光晕和湿漉漉的倒影，整条街道笼罩在朦胧的雨雾中', '', 'demochar001', 'demo-scene-003', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/21/5ba220ce61f2417c9c09b871550efb73.png', NULL, NULL, NULL, 'pending', NULL, 0, '2026-04-22 17:09:08', '2026-04-22 17:14:30');
INSERT INTO `storyboards` VALUES ('383e6cebad8441eb8b16556d064c7cf1', 'demo-drama-001', 1, 6, 6, 'medium', '缓慢拉出', '苏珊陪伴在林小雨身边，两人漫步在街头，苏珊依旧开朗活泼，林小鸟若有所思', '', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-22 16:21:52', '2026-04-22 16:44:42');
INSERT INTO `storyboards` VALUES ('4300568239de4fe6a61af98b20f816c2', 'demo-drama-001', 1, 10, 10, 'close-up', '固定镜头', '林小雨眼底闪过一丝暖意，但表情依旧淡然，只是轻轻颔首，表示接受', '', 'demochar001', 'demo-scene-002', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/21/5ba220ce61f2417c9c09b871550efb73.png', NULL, NULL, NULL, 'pending', NULL, 0, '2026-04-22 17:09:08', '2026-04-22 17:17:47');
INSERT INTO `storyboards` VALUES ('4b64c575f89e4e60af9d94eb977fa134', 'demo-drama-001', 1, 5, 5, 'medium', '固定镜头', '林小雨不慎撞进一个坚实的怀抱，身体微微后仰，伞边缘的水珠飞溅', '', 'demochar001', 'demo-scene-003', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/21/5ba220ce61f2417c9c09b871550efb73.png', NULL, NULL, NULL, 'pending', NULL, 0, '2026-04-22 17:09:08', '2026-04-22 17:10:30');
INSERT INTO `storyboards` VALUES ('4c63e0e991a444c9baeb84d40fb0551a', 'demo-drama-001', 1, 11, 11, 'extreme-close-up', '固定镜头', '林小雨低头，嘴角浮现一抹浅笑，手指轻轻转动着水杯', '', 'demochar001', 'demo-scene-002', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/21/5ba220ce61f2417c9c09b871550efb73.png', NULL, NULL, NULL, 'pending', NULL, 0, '2026-04-22 17:09:08', '2026-04-22 17:17:51');
INSERT INTO `storyboards` VALUES ('5050416050784c68952624d0ff5218cd', 'demo-drama-001', 1, 12, 12, 'close-up', '特写', '苏雨桐手中的画纸上隐约可见一幅都市风景画，画面中有个模糊的西装男子轮廓', '', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:36:31', '2026-04-21 00:14:32');
INSERT INTO `storyboards` VALUES ('5675b269cd9e4c6cbd655016502ff301', 'demo-drama-001', 1, 26, 42, 'wide', '拉镜头', '清晨的城市，朝阳升起，阳光照进林小溪的公寓，她独自站在窗前，手中紧握那本旧笔记本', '（内心独白）五年了，我以为一切都结束了...原来这只是开始。', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:37:48', '2026-04-21 00:13:18');
INSERT INTO `storyboards` VALUES ('5cb61ed22bc74a988ae95a10c9aeabd3', 'demo-drama-001', 1, 29, 45, 'wide', '固定镜头', '城市街道，车流中一辆黑色轿车内，顾言戴着墨镜坐在后座，窗外是林小溪公寓的方向，手中的手机显示着一条短信：\"游戏开始了\"', '', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:37:48', '2026-04-21 00:13:10');
INSERT INTO `storyboards` VALUES ('5f3a314045e74bfb918982de5b1bd8cd', 'demo-drama-001', 1, 11, 11, 'wide', '固定镜头', '林小雨、苏珊、顾辰三人并排走在迷雾笼罩的城市街道上，步伐沉重，周围环境朦胧，三人的命运看似紧密捆绑', '', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-22 16:21:52', '2026-04-22 16:44:31');
INSERT INTO `storyboards` VALUES ('610ca722c9394d478df282ff5f0b8ba3', 'demo-drama-001', 1, 9, 9, 'medium', '固定镜头', '苏珊独自一人时，笑容逐渐收敛，眼神中闪过一丝复杂若有所思的表情，与平日的开朗形成反差', '', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-22 16:21:52', '2026-04-22 16:44:35');
INSERT INTO `storyboards` VALUES ('638a4ed155dd431cb3da6c9053f1aec0', 'demo-drama-001', 1, 22, 38, 'wide', '固定镜头', '地下通道的灯光突然闪烁，远处传来杂乱的脚步声，林小溪和顾言警惕地对视', '（远处脚步声）有人来了！快走！', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:37:48', '2026-04-21 00:13:28');
INSERT INTO `storyboards` VALUES ('67ea1a05ee2642ad991079013b843282', 'demo-drama-001', 1, 9, 9, 'medium', '固定镜头', '顾辰坐在餐桌前，身体略显笨拙地将一杯温水推到林小雨面前，眼神避开她的目光', '谢谢你上次的设计方案', 'demochar002', 'demo-scene-002', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/22/8a691046eb5648dbb3de1a3af1e0c154.png', NULL, NULL, NULL, 'pending', NULL, 0, '2026-04-22 17:09:08', '2026-04-22 17:17:41');
INSERT INTO `storyboards` VALUES ('682f16b6118e4c8bb7fb65ec3450e41f', 'demo-drama-001', 1, 4, 4, 'medium', '推镜头', '林小雨撑着伞匆匆走过街道，低着头快步前行，脚步溅起小小的水花', '', 'demochar001', 'demo-scene-003', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/21/5ba220ce61f2417c9c09b871550efb73.png', NULL, NULL, NULL, 'pending', NULL, 0, '2026-04-22 17:09:08', '2026-04-22 17:10:23');
INSERT INTO `storyboards` VALUES ('68ce0b6ac4144662af3f24000dc73fc9', 'demo-drama-001', 1, 2, 2, 'medium', '手持跟随', '男主角林逸晨步履匆忙地走在人行道上，身穿黑色西装，背着公文包，手里拿着咖啡，时不时查看手表', '', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:36:31', '2026-04-21 00:14:18');
INSERT INTO `storyboards` VALUES ('6dc51d69727b4743b3f1c6a1a5720322', 'demo-drama-001', 1, 8, 8, 'medium', '固定镜头', '苏雨桐站稳身体，捡起散落的画纸，林逸晨帮她捡起掉落的雨伞', '谢谢', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:36:31', '2026-04-21 00:14:27');
INSERT INTO `storyboards` VALUES ('6ed8eb5defb04ba1b56ac4ca2c1ecf61', 'demo-drama-001', 1, 12, 28, 'extreme-close-up', '特写推进', '顾言手腕上露出一道深深的疤痕特写，那是五年前留下的痕迹，林小溪看到后脸色大变', '这疤痕...那是当年...', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:37:48', '2026-04-21 00:13:56');
INSERT INTO `storyboards` VALUES ('70616a7583e64a359326bf6b1a657ec2', 'demo-drama-001', 1, 5, 5, 'close-up', '快速跟拍', '林逸晨刚好走到斑马线中央，看到电动车冲向苏雨桐，他迅速伸手抓住苏雨桐的胳膊将她拉回路边', '小心！', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:36:31', '2026-04-21 00:14:23');
INSERT INTO `storyboards` VALUES ('740c9890119841d0ae70ce719e6a59a8', 'demo-drama-001', 1, 16, 16, 'wide', '航拍俯视', '都市的全景，车流涌动，人群熙攘，每个人都在自己的命运轨道上前行', '', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:36:31', '2026-04-21 00:14:37');
INSERT INTO `storyboards` VALUES ('75ff66d287d34bdab72ed0731d1dcfa1', 'demo-drama-001', 1, 1, 17, 'wide', '缓慢推进', '城市高空远景，俯瞰繁华都市夜景，车流如织，灯光闪烁，镜头缓缓下降扫过高楼林立的CBD区域', '', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:37:48', '2026-04-21 00:14:40');
INSERT INTO `storyboards` VALUES ('7952f4bf269e412c8c794ee121e56f5d', 'demo-drama-001', 1, 19, 35, 'wide', '快速推进', '城市的地下通道内，顾言和林小溪快速奔逃，脚步声在空旷的通道中回响，前方出现分岔口', '（林小溪气喘吁吁）顾言！你到底在躲什么？\\n（顾言）躲得不是我，是真相...五年前的事故不是意外！', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:37:48', '2026-04-21 00:13:45');
INSERT INTO `storyboards` VALUES ('7abe8407a152417492cd6fcd4f07dc61', 'demo-drama-001', 1, 14, 14, 'close-up', '特写', '林逸晨接起手机，屏幕显示\"公司秘书\"', '林总，会议还有十分钟开始', NULL, 'demo-scene-003', NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:36:31', '2026-04-21 00:14:35');
INSERT INTO `storyboards` VALUES ('7b4a57ba50174caf87c4d29b02bcd893', 'demo-drama-001', 1, 11, 27, 'medium', '固定镜头', '顾言停在林小溪面前三步之遥，表情复杂，欲言又止，眼神中闪过痛苦、思念和一丝难以捉摸的情绪', '小溪...好久不见。', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:37:48', '2026-04-21 00:13:58');
INSERT INTO `storyboards` VALUES ('7e3493082f8a4bed98c56ea8d6aec193', 'demo-drama-001', 1, 13, 13, 'wide', '拉镜头', '镜头缓缓拉远，餐厅全景逐渐展现，苏珊的身影在角落位置一闪而过，眼神复杂地看向这边', '', 'demochar003', 'demo-scene-002', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/22/7ad8049033734f8b8d3f59605a135ec2.png', NULL, NULL, NULL, 'pending', NULL, 0, '2026-04-22 17:09:08', '2026-04-22 17:18:07');
INSERT INTO `storyboards` VALUES ('7facac3682e94b97ad070e1c7d46e7b1', 'demo-drama-001', 1, 16, 32, 'wide', '拉镜头', '顾言快步走向咖啡馆后门，回头眼神示意林小溪跟上，林小溪犹豫片刻后快步跟上，两人的身影消失在后门', '（顾言低声）跟我来，我会解释一切...', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:37:48', '2026-04-21 00:13:50');
INSERT INTO `storyboards` VALUES ('80d5966f77db4582afb7b3b882fe14ff', 'demo-drama-001', 1, 10, 10, 'wide', '缓慢拉出', '清晨的阳光照在两人身上，周围是匆忙过路的行人，车流再次流动', '', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:36:31', '2026-04-21 00:14:30');
INSERT INTO `storyboards` VALUES ('80d672f9b3df4f178e95aa078bc4e1ed', 'demo-drama-001', 1, 3, 3, 'medium', '横移', '城市的咖啡馆内，林小雨与闺蜜苏珊相对而坐，苏珊笑容灿烂，活泼开朗地讲述着什么趣事，林小雨偶尔浅笑', '', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-22 16:21:52', '2026-04-22 16:44:48');
INSERT INTO `storyboards` VALUES ('8248df3d824d418dbfcfa236e0639d75', 'demo-drama-001', 1, 10, 10, 'extreme-close-up', '缓慢推进', '林小雨与顾辰对视，彼此的眼神中既有爱恋又充满疑虑，仿佛在试探对方的真心', '', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-22 16:21:52', '2026-04-22 16:44:33');
INSERT INTO `storyboards` VALUES ('87f38dabdf9f43d783f2e3eaf778f206', 'demo-drama-001', 1, 20, 36, 'medium', '固定镜头', '林小溪停下脚步，一把拉住顾言，神情坚定：什么真相？五年前到底发生了什么，你必须告诉我！', '什么真相？五年前到底发生了什么，你必须告诉我！', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:37:48', '2026-04-21 00:13:43');
INSERT INTO `storyboards` VALUES ('8a775078a88f4914bf2558330eaa9c17', 'demo-drama-001', 1, 7, 7, 'close-up', '特写缓慢拉出', '林逸晨低头看着怀中的苏雨桐，两人的目光第一次交汇，时间仿佛静止', '', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:36:31', '2026-04-21 00:14:26');
INSERT INTO `storyboards` VALUES ('8b5b2ccd01ca46b5bdc48f0ef1b1f6d2', 'demo-drama-001', 1, 8, 24, 'extreme-close-up', '固定特写', '林小溪手中的笔记本特写，照片中年轻男子的面容与五年后的顾言逐渐重叠，她的眼眶泛红，泪水在眼角凝聚', '', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:37:48', '2026-04-21 00:14:03');
INSERT INTO `storyboards` VALUES ('8cda385b3e2c489eb0e0b35be2961152', 'demo-drama-001', 1, 23, 39, 'medium', '快速跟拍', '顾言拉着林小溪向左边的通道跑去，身后脚步声越来越近，画面渐暗，只剩下奔跑的脚步声和急促的呼吸声', '', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:37:48', '2026-04-21 00:13:26');
INSERT INTO `storyboards` VALUES ('9242dd2560b24f7d95ffbda97d9455f7', 'demo-drama-001', 1, 1, 1, 'medium', '缓慢推进', '林小雨独自在简约的工作室内专注地绘制设计图纸，窗外夕阳洒落，她神情清冷而专注，手指灵活地移动着铅笔', '', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-22 16:21:52', '2026-04-22 16:44:51');
INSERT INTO `storyboards` VALUES ('9247d03c06664287a0ffe242bb702171', 'demo-drama-001', 1, 6, 6, 'medium', '固定镜头', '苏雨桐被拉到路边，身体踉跄着倒入林逸晨怀中，画板包掉落在地上，画纸散落出来', '啊！', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:36:31', '2026-04-21 00:14:24');
INSERT INTO `storyboards` VALUES ('93cfadc4dd0b412bae24e8cd87972c42', 'demo-drama-001', 1, 18, 34, 'extreme-close-up', '特写', '神秘男子弯腰捡起地上的一枚徽章，徽章上刻着一个神秘的符号，他嘴角露出冷笑', '（冷笑）找到了...', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:37:48', '2026-04-21 00:13:47');
INSERT INTO `storyboards` VALUES ('963c07337a2f494a8b508eddcef36b65', 'demo-drama-001', 1, 1, 1, 'wide', '航拍缓慢推进', '清晨的都市全景，高楼林立，街道上车流如织，阳光透过玻璃幕墙在建筑表面反射出耀眼的光芒', '', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:36:31', '2026-04-21 00:14:17');
INSERT INTO `storyboards` VALUES ('9a5e269f4e1b4f5fa612215edacd6621', 'demo-drama-001', 1, 3, 19, 'medium', '推镜头', '林小溪翻开笔记本，页面上显示着一张模糊的老照片和几行手写文字，她的手指轻轻抚过照片，眼神变得复杂', '（内心独白）五年了，你到底在哪里...', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:37:48', '2026-04-21 00:14:11');
INSERT INTO `storyboards` VALUES ('a507c348fc68426a82900604d8810028', 'demo-drama-001', 1, 14, 30, 'close-up', '快速推镜头', '顾言迅速转头看向窗外，眼神警惕，低声说道：我们不能在这里说话，有人一直在跟踪我。', '我们不能在这里说话，有人一直在跟踪我。', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:37:48', '2026-04-21 00:13:53');
INSERT INTO `storyboards` VALUES ('a711b0c093ae4199b2d0f73f103635a0', 'demo-drama-001', 1, 5, 21, 'medium', '固定镜头', '顾言站在原地，身体微微一顿，显然认出了窗边的女子，手不自觉地握紧门把手，呼吸变得急促', '（内心独白）是她...居然是她...', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:37:48', '2026-04-21 00:14:07');
INSERT INTO `storyboards` VALUES ('a7ccbd870a834cfeafa13d0f28781a4e', 'demo-drama-001', 1, 7, 7, 'close-up', '固定镜头', '顾辰独自在办公室中，眼神深邃若有所思，手中握着一份文件，似乎隐藏着过往的隐秘', '', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-22 16:21:52', '2026-04-22 16:44:40');
INSERT INTO `storyboards` VALUES ('b598dc527f9c4c27939f7092dfc03814', 'demo-drama-001', 1, 25, 41, 'extreme-close-up', '特写', '徽章特写，上面刻着与五年前车祸现场发现的同一符号，画面定格在此', '', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:37:48', '2026-04-21 00:13:23');
INSERT INTO `storyboards` VALUES ('bd252e73bba94a4dbe073032f640a90f', 'demo-drama-001', 1, 2, 2, 'wide', '固定镜头', '顾辰身着简洁的黑色西装，步入公司高层会议室，眼神沉稳而犀利，背后是城市璀璨的天际线', '', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-22 16:21:52', '2026-04-22 16:44:49');
INSERT INTO `storyboards` VALUES ('be818db46cf64de0bc93027acf8614e1', 'demo-drama-001', 1, 12, 12, 'medium', '固定镜头', '顾辰看着林小雨，喉结微微滚动，眼神中流露出复杂的情感', '', 'demochar002', 'demo-scene-002', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/22/8a691046eb5648dbb3de1a3af1e0c154.png', NULL, NULL, NULL, 'pending', NULL, 0, '2026-04-22 17:09:08', '2026-04-22 17:17:59');
INSERT INTO `storyboards` VALUES ('bf1055d695594fc0988dd7c88be68862', 'demo-drama-001', 1, 28, 44, 'close-up', '固定特写', '林小溪的眼神从困惑逐渐变得坚定，她轻声自语：我会找出真相。', '（坚定地）我会找出真相。', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:37:48', '2026-04-21 00:13:12');
INSERT INTO `storyboards` VALUES ('c3dd644f579345afb37b6fd58bec1bdb', 'demo-drama-001', 1, 7, 7, 'medium', '固定镜头', '顾辰一手撑伞，另一只手紧紧攥住林小雨的手腕，身体略显僵硬，语气沉稳', '小心', 'demochar002', 'demo-scene-003', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/22/8a691046eb5648dbb3de1a3af1e0c154.png', NULL, NULL, NULL, 'pending', NULL, 0, '2026-04-22 17:09:08', '2026-04-22 17:16:31');
INSERT INTO `storyboards` VALUES ('c5f5aa045ad14067a897752b98b54eac', 'demo-drama-001', 1, 13, 29, 'medium', '360度环摇', '咖啡馆窗外，雨势变大，雨水模糊了玻璃，店内灯光摇曳，营造出悬疑压抑的氛围，远处仿佛有人影闪过', '', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:37:48', '2026-04-21 00:13:55');
INSERT INTO `storyboards` VALUES ('c93476a982664d89a342a96875c8cae6', 'demo-drama-001', 1, 17, 33, 'medium', '固定镜头', '咖啡馆前门，一位戴着帽子的神秘男子走入，四处张望后在顾言刚才站立的位置停下，地上有一滴血迹', '', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:37:48', '2026-04-21 00:13:49');
INSERT INTO `storyboards` VALUES ('cde6816741ad4dbd8a85730e69b35f4e', 'demo-drama-001', 1, 9, 25, 'medium', '跟拍镜头', '顾言深吸一口气，迈步向林小溪走去，每一步都显得沉重而犹豫，周围的顾客仿佛都消失了，整个咖啡馆只剩下他们两人', '', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:37:48', '2026-04-21 00:14:01');
INSERT INTO `storyboards` VALUES ('d1633e576ebb489ca99bc0ae18b83f31', 'demo-drama-001', 1, 4, 4, 'medium', '推镜头', '绿灯亮起，苏雨桐抬脚准备过马路，这时一辆电动车突然从右侧冲出', '', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:36:31', '2026-04-21 00:14:22');
INSERT INTO `storyboards` VALUES ('d173d0885ec54c8db90ae1d08cba4830', 'demo-drama-001', 1, 6, 6, 'close-up', '固定镜头', '林小雨抬头，对上顾辰深邃的眼眸，眼神中闪过一丝惊慌与错愕', '', 'demochar002', 'demo-scene-003', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/22/8a691046eb5648dbb3de1a3af1e0c154.png', NULL, NULL, NULL, 'pending', NULL, 0, '2026-04-22 17:09:08', '2026-04-22 17:10:39');
INSERT INTO `storyboards` VALUES ('d1a884679b5342a9a76e70a608a6fa71', 'demo-drama-001', 1, 30, 46, 'extreme-close-up', '特写', '顾言手机屏幕特写，信息内容：\"游戏开始了\"，发送号码是一串乱码', '（顾言轻叹）终究还是把你卷入了...', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:37:48', '2026-04-21 00:13:09');
INSERT INTO `storyboards` VALUES ('d944135bc880411e8df0a04ae0d0fa71', 'demo-drama-001', 1, 21, 37, 'close-up', '拉镜头', '顾言转身面向林小溪，表情痛苦纠结，缓缓开口：五年前那场车祸...我父母不是意外死亡，他们是被人...（话未说完）', '五年前那场车祸...我父母不是意外死亡，他们是被人...', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:37:48', '2026-04-21 00:13:40');
INSERT INTO `storyboards` VALUES ('d9e55915d50845ae879586408ce7efdf', 'demo-drama-001', 1, 4, 4, 'close-up', '快速推进', '林小雨与顾辰在一个商务活动中初次相遇，两人目光交汇，各自带有审视与试探的气息，周围人群喧嚣', '', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-22 16:21:52', '2026-04-22 16:44:46');
INSERT INTO `storyboards` VALUES ('dbde1d8fd4234fb2b65c34104731e468', 'demo-drama-001', 1, 13, 13, 'medium', '手持跟随', '林逸晨目送苏雨桐消失在下班高峰的人流中，这时他的手机响起', '（手机铃声）', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:36:31', '2026-04-21 00:14:34');
INSERT INTO `storyboards` VALUES ('e45c355cd1774b918e3992e631a43784', 'demo-drama-001', 1, 15, 31, 'medium', '固定镜头', '林小溪一脸震惊和困惑，但很快恢复冷静，低头看了看手中的笔记本，又抬头看向顾言', '跟踪你？五年前你突然失踪，现在又说被人跟踪...这到底是怎么回事？', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:37:48', '2026-04-21 00:13:52');
INSERT INTO `storyboards` VALUES ('e5524f678a8e49bb82fbedd772a6d0b9', 'demo-drama-001', 1, 6, 22, 'close-up', '特写推进', '林小溪似乎感应到什么，缓缓抬起头，目光与顾言交汇，时间仿佛在这一刻静止，两人都是一脸震惊', '', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:37:48', '2026-04-21 00:14:06');
INSERT INTO `storyboards` VALUES ('e8a5654aadac4c7eb488679fc1c81fe0', 'demo-drama-001', 1, 5, 5, 'extreme-close-up', '固定镜头', '林小雨与顾辰再次单独相遇，两人的距离靠近，眼神中透露出彼此试探与情愫暗生的微妙氛围', '', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-22 16:21:52', '2026-04-22 16:44:44');
INSERT INTO `storyboards` VALUES ('ee9af9b2cfdc4edfa0b1d5a257b5ab26', 'demo-drama-001', 1, 15, 15, 'medium', '固定镜头', '林逸晨接电话的同时，目光再次望向苏雨桐离开的方向', '好，我马上回去', NULL, 'demo-scene-003', NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:36:31', '2026-04-21 00:14:36');
INSERT INTO `storyboards` VALUES ('f2d63fa4824043c7b2f10e24f0eecd25', 'demo-drama-001', 1, 3, 3, 'wide', '固定镜头', '女主角苏雨桐站在十字路口斑马线一端，身穿白色连衣裙，背着画板包，手中撑着蓝色雨伞，目光望向红灯', '', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:36:31', '2026-04-21 00:14:20');
INSERT INTO `storyboards` VALUES ('f803ce2224324a798ed3bf7ab9a16f6f', 'demo-drama-001', 1, 8, 8, 'wide', '固定镜头', '烛光摇曳，水晶吊灯在天花板上折射出细碎耀眼的光芒，窗外黄浦江夜景璀璨如星，高级餐厅内氛围浪漫温馨', '', 'demochar002', 'demo-scene-002', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/22/8a691046eb5648dbb3de1a3af1e0c154.png', NULL, NULL, NULL, 'pending', NULL, 0, '2026-04-22 17:09:08', '2026-04-22 17:16:47');
INSERT INTO `storyboards` VALUES ('f8dee2d002b14b63b082252ee1527fb2', 'demo-drama-001', 1, 2, 18, 'wide', '固定镜头', '咖啡馆内景，窗边座位，一位年轻女子（林小溪）坐在窗边，手中握着一本旧式笔记本，望着窗外雨景，眼神中带着一丝忧虑和期待', '', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:37:48', '2026-04-21 00:14:13');
INSERT INTO `storyboards` VALUES ('fac6e6aa1ded43f4bd2aefc09510247b', 'demo-drama-001', 1, 10, 26, 'close-up', '拉镜头', '林小溪猛然站起，椅子被撞倒发出声响，她难以置信地后退一步，手中紧握的笔记本微微颤抖', '真的是你...顾言？你还活着？', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:37:48', '2026-04-21 00:13:59');
INSERT INTO `storyboards` VALUES ('ff2894200a944761b00f57d90890b15b', 'demo-drama-001', 1, 7, 23, 'medium', '叠化', '回忆片段：五年前的雨夜，同样是这家咖啡馆门前，年轻版的顾言和林小溪在雨中追逐，两人的手几乎要触碰在一起，却被一辆突然驶过的汽车分开', '（画外音女）顾言！不要走！\\n（画外音男）小溪，等我回来！', NULL, NULL, NULL, NULL, NULL, NULL, 'pending', NULL, 1, '2026-04-16 22:37:48', '2026-04-21 00:14:04');
INSERT INTO `storyboards` VALUES ('sb-ep01-s01', 'fe-dark-dragon', 1, 1, 1, 'wide', '航拍俯冲', '镜头从高空俯瞰塔利斯岛全景，宁静的渔村炊烟袅袅。突然远处海面出现多艘海盗船逼近。', NULL, NULL, 'scene-talis-village', NULL, 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/2633a003009541a5bc333136bffa2927.png', NULL, NULL, 'pending', '{\"mood\":\"宁静到紧张\"}', 1, '2026-04-16 21:59:46', '2026-04-20 23:53:33');
INSERT INTO `storyboards` VALUES ('sb-ep01-s02', 'fe-dark-dragon', 1, 1, 2, 'medium', '手持晃动', '村民们四散奔逃，海盗士兵已跳上岸挥舞弯刀砍向房屋，火焰蔓延。', '村民A：海盗来了！快跑！！', NULL, 'scene-talis-village', NULL, 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/2633a003009541a5bc333136bffa2927.png', NULL, NULL, 'pending', '{\"mood\":\"恐慌混乱\"}', 1, '2026-04-16 21:59:46', '2026-04-21 00:11:34');
INSERT INTO `storyboards` VALUES ('sb-ep01-s03', 'fe-dark-dragon', 1, 1, 3, 'medium', '正面推镜', '希达公主穿着便服气喘吁吁地跑进来，抓住马尔斯的手臂。', '希达：马尔斯！求求你！村民们需要你的帮助！', 'char-shiida', 'scene-talis-village', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/21/f69e5c8de2ff4147a4e894227a7863a2.png', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/07c898cace394c39aca262a10dbb1766.jpeg', NULL, NULL, 'pending', '{\"mood\":\"紧急恳求\"}', 0, '2026-04-16 21:59:46', '2026-04-21 01:16:42');
INSERT INTO `storyboards` VALUES ('sb-ep01-s04', 'fe-dark-dragon', 1, 1, 4, 'close-up', '侧面特写', '马尔斯眼神从犹豫变为坚定，握紧拳头，斗篷在风中扬起。', '马尔斯：谢刚、凯因！召集所有人——我们不能再躲藏了。', 'char-mars', 'scene-talis-village', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/07c898cace394c39aca262a10dbb1766.jpeg', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/2633a003009541a5bc333136bffa2927.png', NULL, NULL, 'pending', '{\"mood\":\"觉醒决心\",\"key_moment\":true}', 0, '2026-04-16 21:59:46', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep01-s05', 'fe-dark-dragon', 1, 1, 5, 'wide', '横向移动', '马尔斯持剑冲锋在前，谢刚掩护侧翼，凯因后方射箭支援。激烈战斗场面。', '马尔斯：为了塔利斯！为了所有庇护我们的人！', 'char-mars', 'scene-talis-village', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/07c898cace394c39aca262a10dbb1766.jpeg', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/2633a003009541a5bc333136bffa2927.png', NULL, NULL, 'pending', '{\"mood\":\"热血激昂\"}', 0, '2026-04-16 21:59:46', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep01-s06', 'fe-dark-dragon', 1, 1, 6, 'medium', '缓慢后拉', '战斗结束后马尔斯收剑入鞘，希达站在不远处看着他。', '希达：（独白）这个人……和传闻中的王子不一样。', 'char-shiida', 'scene-talis-village', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/9589d23d3ca64315a7e79e1388ceb7eb.jpeg', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/2633a003009541a5bc333136bffa2927.png', NULL, NULL, 'pending', '{\"mood\":\"温情萌芽\"}', 0, '2026-04-16 21:59:46', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep01-s07', 'fe-dark-dragon', 1, 2, 1, 'wide', '远景固定', '塔利斯城外地平线上帝国军方阵推进，无数军旗猎猎作响。', '守卫长官：帝国军主力……超过三千人！', NULL, 'scene-talis-castle', NULL, 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/4d3c8e4a35134896bbab5232c9374bc9.png', NULL, NULL, 'pending', '{\"mood\":\"绝望压迫\"}', 0, '2026-04-16 21:59:46', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep01-s08', 'fe-dark-dragon', 1, 2, 2, 'medium', '手持晃动', '国王书房内一片混乱，地图被打翻，国王看着窗外火光。', '塔利斯国王：他们是来抓马尔斯的。如果他落入帝国手中……希望就没了。', 'char-talis_king', 'scene-talis-castle', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/ae5059950a37427ab57fd46f87d23276.png', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/4d3c8e4a35134896bbab5232c9374bc9.png', NULL, NULL, 'pending', '{\"mood\":\"紧迫决策\"}', 0, '2026-04-16 21:59:46', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep01-s09', 'fe-dark-dragon', 1, 2, 3, 'wide', '快速推进', '夜色中马尔斯率小队突围，箭矢从身后飞来，他挥剑格挡护送希达前进。', '马尔斯：希达！别回头！往前走！', 'char-mars', 'scene-talis-castle', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/07c898cace394c39aca262a10dbb1766.jpeg', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/4d3c8e4a35134896bbab5232c9374bc9.png', NULL, NULL, 'pending', '{\"mood\":\"生死逃亡\"}', 1, '2026-04-16 21:59:46', '2026-04-21 00:11:40');
INSERT INTO `storyboards` VALUES ('sb-ep01-s10', 'fe-dark-dragon', 1, 2, 4, 'close-up', '正反打', '码头边国王将戒指交给马尔斯，船只已备好。', '塔利斯国王：这艘船送你们去奥利安。马尔斯……为每一个受苦的人去解放它吧。', 'char-talis_king', 'scene-talis-castle', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/ae5059950a37427ab57fd46f87d23276.png', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/4d3c8e4a35134896bbab5232c9374bc9.png', NULL, NULL, 'pending', '{\"mood\":\"庄重嘱托\"}', 1, '2026-04-16 21:59:46', '2026-04-21 00:12:07');
INSERT INTO `storyboards` VALUES ('sb-ep01-s11', 'fe-dark-dragon', 1, 2, 5, 'wide', '航拍拉升', '月光下海面航行，马尔斯和希达并肩站在船头。镜头拉高船只变成小点。', '马尔斯：再见塔利斯……你好阿卡奈亚。', 'char-mars', 'scene-talis-castle', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/07c898cace394c39aca262a10dbb1766.jpeg', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/4d3c8e4a35134896bbab5232c9374bc9.png', NULL, NULL, 'pending', '{\"mood\":\"史诗启程\",\"episode_end\":true}', 1, '2026-04-16 21:59:46', '2026-04-21 00:12:14');
INSERT INTO `storyboards` VALUES ('sb-ep02-s01', 'fe-dark-dragon', 2, 3, 1, 'wide', '固定远景', '船只在晨光中抵达奥利安海岸，白垩岩崖和金色沙滩映入眼帘。马尔斯跳上沙滩。', NULL, NULL, 'scene-orlean-coast', NULL, 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/17/ad6d04baca794c56bebc1d543e29637b.png', NULL, NULL, 'pending', '{\"mood\":\"新大陆\"}', 0, '2026-04-16 21:59:46', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep02-s02', 'fe-dark-dragon', 2, 3, 2, 'medium', '侧面跟拍', '马尔斯一行在海岸边遭遇马其顿巡逻队，双方拔出武器对峙。', '巡逻队长：站住！这片海岸已经被多鲁亚帝国接管了！', NULL, 'scene-orlean-coast', NULL, 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/17/ad6d04baca794c56bebc1d543e29637b.png', NULL, NULL, 'pending', '{\"mood\":\"首次交锋\"}', 0, '2026-04-16 21:59:46', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep02-s03', 'fe-dark-dragon', 2, 3, 3, 'wide', '快速剪辑', '战斗快速展开——凯因射倒前排敌人、马尔斯突进斩杀指挥官。巡逻队溃散。', '凯因：这就是帝国的精锐？太弱了吧！', 'char-cain', 'scene-orlean-coast', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/8a454b3d23eb46e3af1b5a40c1e9f975.png', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/17/ad6d04baca794c56bebc1d543e29637b.png', NULL, NULL, 'pending', '{\"mood\":\"速胜\"}', 0, '2026-04-16 21:59:46', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep02-s04', 'fe-dark-dragon', 2, 3, 4, 'medium', '推镜', '俘虏的敌军士兵跪地求饶，透露奥利安王城被围困的情报。', '俘虏：求饶命！奥利安王城……被马其顿军团围了一个月了！城里快撑不住了！', NULL, 'scene-orlean-coast', NULL, 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/17/ad6d04baca794c56bebc1d543e29637b.png', NULL, NULL, 'pending', '{\"mood\":\"情报获取\"}', 0, '2026-04-16 21:59:46', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep02-s05', 'fe-dark-dragon', 2, 4, 1, 'wide', '航拍俯冲', '奥利安王城全景——城墙残破，外围布满马其顿军营，烟柱从城中升起。', NULL, NULL, 'scene-orlen-castle', NULL, 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/dfad0cba15cd46a5bad70023e7e78449.png', NULL, NULL, 'pending', '{\"mood\":\"围城压迫\"}', 0, '2026-04-16 21:59:46', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep02-s06', 'fe-dark-dragon', 2, 4, 2, 'medium', '手持跟拍', '马尔斯率义军从侧翼发起突袭，突破马其顿包围圈。混乱中箭矢横飞。', '马尔斯：哈丁！我们是来救你们的！坚持住！', 'char-mars', 'scene-orlen-castle', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/07c898cace394c39aca262a10dbb1766.jpeg', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/dfad0cba15cd46a5bad70023e7e78449.png', NULL, NULL, 'pending', '{\"mood\":\"突围激战\"}', 0, '2026-04-16 21:59:46', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep02-s07', 'fe-dark-dragon', 2, 4, 3, 'close-up', '正反打', '城门口马尔斯与哈丁汇合。两人互相打量对方——未来的战友初次见面。', '哈丁：你就是马尔斯？……比我想象中的年轻。但你的剑术我认可。', 'char-hardin', 'scene-orlen-castle', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/89042316e7d3497bb87520472acc4417.png', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/dfad0cba15cd46a5bad70023e7e78449.png', NULL, NULL, 'pending', '{\"mood\":\"英雄相惜\"}', 0, '2026-04-16 21:59:46', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep02-s08', 'fe-dark-dragon', 2, 4, 4, 'wide', '后拉', '马其顿指挥官被击败后剩余敌军撤退。城门大开，奥利安士兵欢呼涌出。', '士兵们：万岁！援军来了！奥利安得救了！', NULL, 'scene-orlen-castle', NULL, 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/dfad0cba15cd46a5bad70023e7e78449.png', NULL, NULL, 'pending', '{\"mood\":\"胜利解放\"}', 0, '2026-04-16 21:59:46', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep02-s09', 'fe-dark-dragon', 2, 4, 5, 'medium', '缓慢横移', '王城内哈丁向马尔斯介绍奥利安的情况，地图铺在桌上。', '哈丁：马其顿不是唯一的威胁。整个阿卡奈亚大陆都在帝国的铁蹄之下。要赢，我们需要更多的盟友。', 'char-hardin', 'scene-orlen-castle', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/89042316e7d3497bb87520472acc4417.png', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/dfad0cba15cd46a5bad70023e7e78449.png', NULL, NULL, 'pending', '{\"mood\":\"战略规划\"}', 0, '2026-04-16 21:59:46', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep02-s10', 'fe-dark-dragon', 2, 4, 6, 'close-up', '特写', '马尔斯看着地图上标注的各国位置，眼神坚定。', '马尔斯：那我们就一个一个去解放。从现在开始——奥利安就是我们第一个根据地。', 'char-mars', 'scene-orlen-castle', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/07c898cace394c39aca262a10dbb1766.jpeg', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/dfad0cba15cd46a5bad70023e7e78449.png', NULL, NULL, 'pending', '{\"mood\":\"决心确立\",\"episode_end\":true}', 0, '2026-04-16 21:59:46', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep03-s01', 'fe-dark-dragon', 3, 5, 1, 'medium', '推进', '森林深处秘密营地，妮娜公主站在中央大帐前迎接马尔斯一行。她身后是残破的阿卡奈亚国旗。', NULL, NULL, 'scene-akaneia-resistance', NULL, 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/be45b8c3aafd4b949b0de849adcd6644.png', NULL, NULL, 'pending', '{\"mood\":\"神秘相遇\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep03-s02', 'fe-dark-dragon', 3, 5, 2, 'close-up', '正面特写', '妮娜的面部特写——金发蓝眼，表情庄重而疲惫。她直视马尔斯的眼睛。', '妮娜：你就是安里王室最后的血脉……马尔斯王子。我是阿卡奈亚的妮娜。', 'char-nina', 'scene-akaneia-resistance', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/19/1013d36a492542249e21808eb1f067e4.png', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/be45b8c3aafd4b949b0de849adcd6644.png', NULL, NULL, 'pending', '{\"mood\":\"正式介绍\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep03-s03', 'fe-dark-dragon', 3, 5, 3, 'medium', '过肩镜头', '妮娜讲述阿卡奈亚灭亡的经过。闪回画面叠加在她的面部轮廓上——燃烧的城市、逃难的人民。', '妮娜：那一夜……火焰吞没了整座王城。父王母后……所有的臣民……只有我们少数人逃了出来。', 'char-nina', 'scene-akaneia-resistance', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/19/1013d36a492542249e21808eb1f067e4.png', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/be45b8c3aafd4b949b0de849adcd6644.png', NULL, NULL, 'pending', '{\"mood\":\"悲剧回忆\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep03-s04', 'fe-dark-dragon', 3, 5, 4, 'close-up', '反应镜头', '马尔斯听完后的表情——同情与愤怒交织。他握紧拳头。', '马尔斯：（低声）帝国会为这一切付出代价的。我向你保证，妮娜公主。', 'char-mars', 'scene-akaneia-resistance', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/07c898cace394c39aca262a10dbb1766.jpeg', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/be45b8c3aafd4b949b0de849adcd6644.png', NULL, NULL, 'pending', '{\"mood\":\"共情与承诺\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep03-s05', 'fe-dark-dragon', 3, 5, 5, 'medium', '中景', '妮娜从怀中取出火焰纹章徽盾——古老的封印之盾散发着微弱的光芒。', NULL, 'char-nina', 'scene-akaneia-resistance', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/19/1013d36a492542249e21808eb1f067e4.png', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/be45b8c3aafd4b949b0de849adcd6644.png', NULL, NULL, 'pending', '{\"mood\":\"圣物展示\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep03-s06', 'fe-dark-dragon', 3, 5, 6, 'close-up', '特写', '妮娜将火焰纹章递向马尔斯。', '妮娜：这是火焰纹章……阿卡奈亚王室代代相传的封印之盾。它能增幅神器的力量、压制暗黑之力。现在——它属于你了。', 'char-nina', 'scene-akaneia-resistance', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/19/1013d36a492542249e21808eb1f067e4.png', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/be45b8c3aafd4b949b0de849adcd6644.png', NULL, NULL, 'pending', '{\"mood\":\"权力交接\",\"key_moment\":true}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep03-s07', 'fe-dark-dragon', 3, 5, 7, 'wide', '后拉', '马尔斯接过火焰纹章，周围所有人（希达、谢刚、哈丁等）注视着这一刻。营地上空星光初现。', '妮娜：带着它去吧，马尔斯。让火焰之光照亮整个大陆——就像它曾经照亮阿卡奈亚一样。', 'char-nina', 'scene-akaneia-resistance', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/19/1013d36a492542249e21808eb1f067e4.png', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/be45b8c3aafd4b949b0de849adcd6644.png', NULL, NULL, 'pending', '{\"mood\":\"史诗传承\",\"episode_end\":true}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep04-s01', 'fe-dark-dragon', 4, 6, 1, 'wide', '航拍', '龙人岛的奇异景观——荧光植物遍布岸边，紫红色天空下空气中有魔法粒子飘浮。马尔斯一行踏上岛屿。', NULL, NULL, 'dragon-island-entrance', NULL, 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/47053324a58247db961a2ed6afae90c8.png', NULL, NULL, 'pending', '{\"mood\":\"奇幻异境\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep04-s02', 'fe-dark-dragon', 4, 6, 2, 'medium', '低角度仰拍', '玛奴从岩石后方现身——半人半龙的异族特征清晰可见（竖瞳尖耳），周身环绕着龙气，神情愤怒。', NULL, 'char-manu', 'dragon-island-entrance', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/dbc6e092d0ec444788df85652d68c3a4.png', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/47053324a58247db961a2ed6afae90c8.png', NULL, NULL, 'pending', '{\"mood\":\"紧张对峙\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep04-s03', 'fe-dark-dragon', 4, 6, 3, 'close-up', '正反打', '玛奴质问人类闯入者，声音中带着古老种族的威严。', '玛奴：人类……你们总是带来战争和毁灭。这片土地不欢迎你们。', 'char-manu', 'dragon-island-entrance', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/dbc6e092d0ec444788df85652d68c3a4.png', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/47053324a58247db961a2ed6afae90c8.png', NULL, NULL, 'pending', '{\"mood\":\"种族冲突\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep04-s04', 'fe-dark-dragon', 4, 6, 4, 'medium', '平视', '马尔斯没有拔剑而是放下武器，以诚意回应玛奴的敌意。', '马尔斯：我不是来征服的。我来这里是为了寻找对抗暗黑力量的方法——为了所有生灵，包括龙人族。', 'char-mars', 'dragon-island-entrance', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/07c898cace394c39aca262a10dbb1766.jpeg', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/47053324a58247db961a2ed6afae90c8.png', NULL, NULL, 'pending', '{\"mood\":\"化解敌意\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep04-s05', 'fe-dark-dragon', 4, 6, 5, 'close-up', '特写玛奴的表情变化', '玛奴眼中的愤怒逐渐消退，取而代之的是审视和一丝惊讶。', '玛奴：（独白）这个人类……他的眼中没有贪婪。只有……纯粹的意志。', 'char-manu', 'dragon-island-entrance', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/dbc6e092d0ec444788df85652d68c3a4.png', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/47053324a58247db961a2ed6afae90c8.png', NULL, NULL, 'pending', '{\"mood\":\"态度转变\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep04-s06', 'fe-dark-dragon', 4, 7, 1, 'wide', '环境展示', '进入龙人洞穴内部——幽深的空间里发光苔藓和水晶簇提供照明，远处传来低沉的咆哮声。', NULL, NULL, 'dragon-cave', NULL, 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/74e28bf66cdd4c3381108dc2cf650a97.png', NULL, NULL, 'pending', '{\"mood\":\"危险探索\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep04-s07', 'fe-dark-dragon', 4, 7, 2, 'wide', '快速摇摄', '堕落地龙从黑暗中扑出！巨大的身躯和利爪撕裂空气。马尔斯和玛奴联手迎战。', NULL, NULL, 'dragon-cave', NULL, 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/74e28bf66cdd4c3381108dc2cf650a97.png', NULL, NULL, 'pending', '{\"mood\":\"突发战斗\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep04-s08', 'fe-dark-dragon', 4, 7, 3, 'medium', '动作跟随', '哥多从洞穴深处出现——白发长者手持发光法杖释放神圣魔法驱散堕地龙。龙人战士形态威严。', NULL, 'char-gotoh', 'dragon-cave', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/246ec600f11b42898a92a26e61c985c3.png', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/74e28bf66cdd4c3381108dc2cf650a97.png', NULL, NULL, 'pending', '{\"mood\":\"强力支援\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep04-s09', 'fe-dark-dragon', 4, 7, 4, 'close-up', '正面特写', '哥多注视着马尔斯，千年智慧的目光仿佛看穿了一切。', '哥多：你就是那个人……预言中的少年。命运之轮已经开始转动了。', 'char-gotoh', 'dragon-cave', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/246ec600f11b42898a92a26e61c985c3.png', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/74e28bf66cdd4c3381108dc2cf650a97.png', NULL, NULL, 'pending', '{\"mood\":\"预言揭示\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep04-s10', 'fe-dark-dragon', 4, 7, 5, 'wide', '后拉', '洞穴深处，哥多向众人示意前方有更深的道路。马尔斯回头看向洞口方向的光明。', NULL, 'char-gotoh', 'dragon-cave', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/246ec600f11b42898a92a26e61c985c3.png', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/74e28bf66cdd4c3381108dc2cf650a97.png', NULL, NULL, 'pending', '{\"mood\":\"新的使命\",\"episode_end\":true}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep06-s01', 'fe-dark-dragon', 6, 11, 1, 'wide', '横向移动', '格拉边境防线前两军对峙。义军在左侧，格拉军队在右侧。林克骑马站在格拉阵线最前方。', NULL, NULL, 'gra-border', NULL, 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/497bba35bb6c4f0b84c4fe5f03273d6a.png', NULL, NULL, 'pending', '{\"mood\":\"内战前夕\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep06-s02', 'fe-dark-dragon', 6, 11, 2, 'medium', '长焦压缩', '林克的面部特写——表情矛盾痛苦。他的手握住剑柄又松开反复多次。', NULL, 'char-link', 'gra-border', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/2dc490f88c5645509149e8056110b577.png', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/497bba35bb6c4f0b84c4fe5f03273d6a.png', NULL, NULL, 'pending', '{\"mood\":\"内心挣扎\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep06-s03', 'fe-dark-dragon', 6, 11, 3, 'medium', '正面对话', '战斗爆发前的短暂停火。马尔斯骑马上前与林克对话。两人之间隔着一段距离。', '马尔斯：林克王子！你的父亲背叛了阿卡奈亚——但你不一定要继承他的罪孽！', 'char-mars', 'gra-border', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/07c898cace394c39aca262a10dbb1766.jpeg', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/497bba35bb6c4f0b84c4fe5f03273d6a.png', NULL, NULL, 'pending', '{\"mood\":\"劝降\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep06-s04', 'fe-dark-dragon', 6, 12, 1, 'wide', '俯拍', '格拉王宫大殿内部全景。黑金色调的奢华空间令人窒息。王座上的国王身影模糊不清。', NULL, NULL, 'gra-throne-room', NULL, 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/a4746d58c3db416e9a5f72e863a1a8bc.png', NULL, NULL, 'pending', '{\"mood\":\"压抑王宫\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep06-s05', 'fe-dark-dragon', 6, 12, 2, 'close-up', '侧光特写', '格拉国王的脸——肥胖、贪婪、暴戾。他正在大笑着下达残酷的命令。', '格拉国王：杀掉他们！把那个叛徒马尔斯的头挂到城门上！谁敢后退一律斩立决！', 'char-gra_king', 'gra-throne-room', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/4fd5bb795e2e4c148269c5edf7cac63b.png', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/a4746d58c3db416e9a5f72e863a1a8bc.png', NULL, NULL, 'pending', '{\"mood\":\"暴君嘴脸\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep06-s06', 'fe-dark-dragon', 6, 12, 3, 'medium', '缓慢推镜', '林克独自走进大殿。他的脚步声在大理石地面回响。两侧侍从纷纷退避。', NULL, 'char-link', 'gra-throne-room', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/2dc490f88c5645509149e8056110b577.png', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/a4746d58c3db416e9a5f72e863a1a8bc.png', NULL, NULL, 'pending', '{\"mood\":\"孤身赴会\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep06-s07', 'fe-dark-dragon', 6, 12, 4, 'close-up', '正反打交替', '林克与父亲的对峙——全剧最沉重的对话场景。', '林克：父亲……你当年出卖阿卡奈亚的时候想过今天吗？', 'char-link', 'gra-throne-room', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/2dc490f88c5645509149e8056110b577.png', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/a4746d58c3db416e9a5f72e863a1a8bc.png', NULL, NULL, 'pending', '{\"mood\":\"父子对决\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep06-s08', 'fe-dark-dragon', 6, 12, 5, 'extreme-close-up', '极端特写', '格拉国王狂怒的表情转为惊愕——林克的剑已刺入他的胸膛。慢镜头中鲜血滴落大理石地面。', '格拉国王：你……你这个逆子……！！', 'char-gra_king', 'gra-throne-room', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/4fd5bb795e2e4c148269c5edf7cac63b.png', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/a4746d58c3db416e9a5f72e863a1a8bc.png', NULL, NULL, 'pending', '{\"mood\":\"弑父悲剧\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep06-s09', 'fe-dark-dragon', 6, 12, 6, 'medium', '高角度俯拍', '林克跪在父亲的尸体旁。剑从他手中滑落发出金属撞击声。他没有哭但肩膀剧烈颤抖。', '林克：（低声几乎听不见）原谅我……父亲。这是……格拉最后的救赎。', 'char-link', 'gra-throne-room', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/2dc490f88c5645509149e8056110b577.png', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/a4746d58c3db416e9a5f72e863a1a8bc.png', NULL, NULL, 'pending', '{\"mood\":\"悲剧余韵\",\"key_moment\":true}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep06-s10', 'fe-dark-dragon', 6, 12, 7, 'wide', '缓慢后拉', '大殿门口马尔斯和众人在沉默中注视着这一幕。林克站起转身面向他们——脸上带着一种死寂后的坚定。', '林克：格拉军队……从现在开始听从马尔斯殿下的命令。这是我唯一能做的补偿。', 'char-link', 'gra-throne-room', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/2dc490f88c5645509149e8056110b577.png', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/a4746d58c3db416e9a5f72e863a1a8bc.png', NULL, NULL, 'pending', '{\"mood\":\"赎罪归顺\",\"episode_end\":true}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep07-s01', 'fe-dark-dragon', 7, 13, 1, 'wide', '史诗级广角', '格鲁尼亚平原上一望无际的重骑兵方阵正向义军推进。地面的震动通过镜头传递给观众。战鹰在天空盘旋。', NULL, NULL, 'grunia-plains', NULL, 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/e09411c34353442ca652539e61303368.png', NULL, NULL, 'pending', '{\"mood\":\"史诗大战\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep07-s02', 'fe-dark-dragon', 7, 13, 2, 'medium', '侧面跟随', '卡缪骑黑马冲在最前方——冰蓝色短发、冷漠眼神、黑色重甲。他是\"格鲁尼亚之狼\"。', NULL, 'char-camus', 'grunia-plains', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/8ecf36804fb246d5a70dea2de99cad73.png', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/e09411c34353442ca652539e61303368.png', NULL, NULL, 'pending', '{\"mood\":\"强敌登场\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep07-s03', 'fe-dark-dragon', 7, 13, 3, 'wide', '快速剪辑', '双方骑兵碰撞的瞬间——金属撞击声、马嘶声、战士怒吼交织在一起。混乱激烈的骑兵战。', NULL, NULL, 'grunia-plains', NULL, 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/e09411c34353442ca652539e61303368.png', NULL, NULL, 'pending', '{\"mood\":\"激战高潮\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep07-s04', 'fe-dark-dragon', 7, 13, 4, 'close-up', '慢动作特写', '卡缪与马尔斯在乱军中擦身而过。两人的武器相撞迸出火花。时间仿佛在这一刻凝固。', NULL, 'char-mars', 'grunia-plains', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/07c898cace394c39aca262a10dbb1766.jpeg', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/e09411c34353442ca652539e61303368.png', NULL, NULL, 'pending', '{\"mood\":\"宿命交锋\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep07-s05', 'fe-dark-dragon', 7, 14, 1, 'wide', '环境展示', '格鲁尼亚城堡大厅内部——历代名将的铠甲和兵器作为装饰挂在石墙上。中央圆形区域是决斗场。夕阳透过高窗射入。', NULL, NULL, 'grunia-castle', NULL, 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/fd376b6a1f7a45689d0b9a16e621dbca.png', NULL, NULL, 'pending', '{\"mood\":\"肃穆决斗场\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep07-s06', 'fe-dark-dragon', 7, 14, 2, 'medium', '环绕拍摄', '卡缪和马尔斯面对面站立。周围所有人退开形成一个圆圈。只有他们两个和彼此的武器。', NULL, 'char-camus', 'grunia-castle', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/8ecf36804fb246d5a70dea2de99cad73.png', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/fd376b6a1f7a45689d0b9a16e621dbca.png', NULL, NULL, 'pending', '{\"mood\":\"决战氛围\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep07-s07', 'fe-dark-dragon', 7, 14, 3, 'close-up', '快速剪辑', '一对一决斗——剑与枪的交锋。每一击都精准致命。汗水飞溅、呼吸急促、眼神锐利如刀。', '卡缪：不错的剑术……但你还是太年轻了。', 'char-camus', 'grunia-castle', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/8ecf36804fb246d5a70dea2de99cad73.png', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/fd376b6a1f7a45689d0b9a16e621dbca.png', NULL, NULL, 'pending', '{\"mood\":\"技艺切磋\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep07-s08', 'fe-dark-dragon', 7, 14, 4, 'extreme-close-up', '极端特写', '决胜一瞬间——马尔斯找到卡缪防御的破绽将剑尖停在对方的喉咙前。', NULL, 'char-mars', 'grunia-castle', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/07c898cace394c39aca262a10dbb1766.jpeg', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/fd376b6a1f7a45689d0b9a16e621dbca.png', NULL, NULL, 'pending', '{\"mood\":\"胜负分晓\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep07-s09', 'fe-dark-dragon', 7, 14, 5, 'medium', '反应镜头', '马尔斯收回剑。他伸出手想拉起卡缪——不是羞辱而是尊重。', '马尔斯：我不杀值得尊敬的对手。卡缪……你的忠诚应该属于更好的主人。', 'char-mars', 'grunia-castle', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/07c898cace394c39aca262a10dbb1766.jpeg', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/fd376b6a1f7a45689d0b9a16e621dbca.png', NULL, NULL, 'pending', '{\"mood\":\"饶恕与尊重\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep07-s10', 'fe-dark-dragon', 7, 14, 6, 'wide', '后拉', '卡缪看着马尔斯伸出的手片刻后转身离去。他的背影消失在暗处——假死隐退的开始。', NULL, 'char-camus', 'grunia-castle', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/8ecf36804fb246d5a70dea2de99cad73.png', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/fd376b6a1f7a45689d0b9a16e621dbca.png', NULL, NULL, 'pending', '{\"mood\":\"神秘退场\",\"key_moment\":\"卡缪假死伏笔\",\"episode_end\":true}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep08-s01', 'fe-dark-dragon', 8, 15, 1, 'wide', '缓慢推进', '黎明时分的阿利提亚边境。古道穿过丘陵通向远方被战火熏黑的天际线。晨雾中马尔斯停下脚步。', NULL, NULL, 'altea-border', NULL, 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/797f463542c74680b12c2012c51d192a.png', NULL, NULL, 'pending', '{\"mood\":\"归乡感伤\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep08-s02', 'fe-dark-dragon', 8, 15, 2, 'close-up', '侧面特写', '马尔斯的侧脸——眼眶微微泛红但强忍着不流露。他的手抚摸着路边残破的界碑。', '马尔斯：（低声）三年了……我终于回来了，父亲。', 'char-mars', 'altea-border', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/07c898cace394c39aca262a10dbb1766.jpeg', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/797f463542c74680b12c2012c51d192a.png', NULL, NULL, 'pending', '{\"mood\":\"情感爆发边缘\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep08-s03', 'fe-dark-dragon', 8, 15, 3, 'medium', '过肩镜头', '希达从身后轻轻握住马尔斯的手。两人并肩望向阿利提亚的方向。', NULL, 'char-shiida', 'altea-border', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/9589d23d3ca64315a7e79e1388ceb7eb.jpeg', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/797f463542c74680b12c2012c51d192a.png', NULL, NULL, 'pending', '{\"mood\":\"陪伴与支持\",\"romantic_beat\":true}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep08-s04', 'fe-dark-dragon', 8, 16, 1, 'wide', '快速推镜', '阿利提亚王城攻防战——义军从三面发起总攻。城墙上帝国守军顽强抵抗。投石机和箭塔齐发。', NULL, NULL, 'altea-throne-room', NULL, 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/d09c1530c81b4e44b840eaae05c51fc3.png', NULL, NULL, 'pending', '{\"mood\":\"复国决战\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep08-s05', 'fe-dark-dragon', 8, 16, 2, 'wide', '航拍俯冲', '马尔斯率突击队率先登上城墙缺口！旗帜在风中展开——阿利提亚的蓝银色国旗重新飘扬在城头。', NULL, 'char-mars', 'altea-throne-room', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/07c898cace394c39aca262a10dbb1766.jpeg', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/d09c1530c81b4e44b840eaae05c51fc3.png', NULL, NULL, 'pending', '{\"mood\":\"夺旗时刻\",\"key_moment\":\"收复王城\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep08-s06', 'fe-dark-dragon', 8, 16, 3, 'medium', '缓慢推进', '战斗结束后的王座大厅。阳光透过彩色玻璃穹顶洒下斑驳光影。地上摆放着鲜花和祭品——祭奠先王。', NULL, NULL, 'altea-throne-room', NULL, 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/d09c1530c81b4e44b840eaae05c51fc3.png', NULL, NULL, 'pending', '{\"mood\":\"肃穆哀悼\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep08-s07', 'fe-dark-dragon', 8, 16, 4, 'close-up', '正面特写', '马尔斯跪在祭品前的背影。他低下头肩膀微微颤抖。', NULL, 'char-mars', 'altea-throne-room', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/07c898cace394c39aca262a10dbb1766.jpeg', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/d09c1530c81b4e44b840eaae05c51fc3.png', NULL, NULL, 'pending', '{\"mood\":\"悼念父亲\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep08-s08', 'fe-dark-dragon', 8, 16, 5, 'medium', '后拉', '马尔斯站起转身面对所有战友们。阳光照在他脸上。', NULL, 'char-mars', 'altea-throne-room', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/07c898cace394c39aca262a10dbb1766.jpeg', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/d09c1530c81b4e44b840eaae05c51fc3.png', NULL, NULL, 'pending', '{\"mood\":\"宣告复国\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep08-s09', 'fe-dark-dragon', 8, 16, 6, 'wide', '环绕拉升', '所有角色齐聚王座大厅——马尔斯、希达、妮娜、密涅瓦、哈丁、林克……每个人脸上都带着不同的表情（坚定/欣慰/期待）。', NULL, NULL, 'altea-throne-room', NULL, 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/d09c1530c81b4e44b840eaae05c51fc3.png', NULL, NULL, 'pending', '{\"mood\":\"全员集结\",\"episode_end\":true}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep09-s01', 'fe-dark-dragon', 9, 17, 1, 'wide', '缓慢推进', '卡达因神殿内景——纯白石柱直达穹顶，地面刻满发光的神圣符文。空气中有金色尘埃在光束中漂浮。', NULL, NULL, 'kadain-shrine', NULL, 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/a0bc9689ec0f497e8be04788d38592e3.png', NULL, NULL, 'pending', '{\"mood\":\"神圣庄严\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep09-s02', 'fe-dark-dragon', 9, 17, 2, 'wide', '仰拍特写', '殿堂尽头的高台上——一把剑悬浮在空中散发着柔和的光芒。那就是法尔西昂，光之圣剑。', NULL, NULL, 'kadain-shrine', NULL, 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/a0bc9689ec0f497e8be04788d38592e3.png', NULL, NULL, 'pending', '{\"mood\":\"神器显现\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep09-s03', 'fe-dark-dragon', 9, 17, 3, 'close-up', '反应镜头', '马尔斯走向法尔西昂。当他伸手触碰剑柄时整个大殿的光芒瞬间暴涨然后稳定下来。剑选择了他。', NULL, 'char-mars', 'kadain-shrine', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/07c898cace394c39aca262a10dbb1766.jpeg', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/a0bc9689ec0f497e8be04788d38592e3.png', NULL, NULL, 'pending', '{\"mood\":\"神器认主\",\"key_moment\":true}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep09-s04', 'fe-dark-dragon', 9, 17, 4, 'medium', '正反打', '妮娜将火焰纹章放在法尔西昂旁边。两者产生共鸣——封印之盾增幅了光之剑的力量。', NULL, 'char-nina', 'kadain-shrine', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/19/1013d36a492542249e21808eb1f067e4.png', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/a0bc9689ec0f497e8be04788d38592e3.png', NULL, NULL, 'pending', '{\"mood\":\"双神器共鸣\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep09-s05', 'fe-dark-dragon', 9, 18, 1, 'wide', '360度旋转', '龙人圣所——没有天花板只有无尽星河旋涡。哥多站在光芒构成的平台中央等待。', NULL, 'char-gotoh', 'dragon-sanctuary', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/246ec600f11b42898a92a26e61c985c3.png', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/f697bccb5a4243ccb439583ad466cfdd.png', NULL, NULL, 'pending', '{\"mood\":\"超凡圣地\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep09-s06', 'fe-dark-dragon', 9, 18, 2, 'medium', '缓慢推进', '哥多向马尔斯传授星光魔法。古老的语言从他口中流出化作星点融入马尔斯体内。', NULL, 'char-gotoh', 'dragon-sanctuary', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/246ec600f11b42898a92a26e61c985c3.png', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/f697bccb5a4243ccb439583ad466cfdd.png', NULL, NULL, 'pending', '{\"mood\":\"魔法传承\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep09-s07', 'fe-dark-dragon', 9, 18, 3, 'close-up', '特写', '马尔斯睁开眼睛——瞳孔中有星光流转。他抬起手掌心凝聚出一团星光。', NULL, 'char-mars', 'dragon-sanctuary', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/07c898cace394c39aca262a10dbb1766.jpeg', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/f697bccb5a4243ccb439583ad466cfdd.png', NULL, NULL, 'pending', '{\"mood\":\"力量觉醒\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep09-s08', 'fe-dark-dragon', 9, 18, 4, 'medium', '中景', '哥多解释星光魔法的作用——唯一能破除卡涅夫暗黑屏障的法术。', NULL, 'char-gotoh', 'dragon-sanctuary', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/246ec600f11b42898a92a26e61c985c3.png', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/f697bccb5a4243ccb439583ad466cfdd.png', NULL, NULL, 'pending', '{\"mood\":\"关键情报\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep09-s09', 'fe-dark-dragon', 9, 18, 5, 'wide', '后拉', '众人站在龙人圣所中准备就绪。马尔斯手持法尔西昂，身上同时有火焰纹章和星光的加持。', '哥多：去吧，星之王马尔斯。你的命运不是逃避——是终结这百年的轮回。', 'char-gotoh', 'dragon-sanctuary', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/246ec600f11b42898a92a26e61c985c3.png', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/f697bccb5a4243ccb439583ad466cfdd.png', NULL, NULL, 'pending', '{\"mood\":\"最终启程\",\"episode_end\":true}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep10-s01', 'fe-dark-dragon', 10, 19, 1, 'wide', '史诗航拍', '多鲁亚帝国本土全景——焦黑的火山岩地貌，硫磺烟雾喷涌，暗红色天空下义军大军的剪影在地平线上推进。', NULL, NULL, 'dolhr-territory', NULL, 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/0734211ae8ad40daaabe98f057289b81.png', NULL, NULL, 'pending', '{\"mood\":\"末日征途\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep10-s02', 'fe-dark-dragon', 10, 19, 2, 'wide', '横向快速移动', '义军各部队协同作战突破帝国防线。马其顿龙骑兵空中突袭、格鲁尼亚重骑地面冲锋、奥利安步兵两翼包抄。', NULL, NULL, 'dolhr-territory', NULL, 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/0734211ae8ad40daaabe98f057289b81.png', NULL, NULL, 'pending', '{\"mood\":\"联合攻势\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep10-s03', 'fe-dark-dragon', 10, 19, 3, 'medium', '跟拍', '马尔斯冲在最前方。法尔西昂在他手中发出耀眼的白光所到之处帝国的黑暗力量纷纷溃散。', '马尔斯：全军听令——目标暗黑神殿！一个不留地推进！！', 'char-mars', 'dolhr-territory', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/07c898cace394c39aca262a10dbb1766.jpeg', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/0734211ae8ad40daaabe98f057289b81.png', NULL, NULL, 'pending', '{\"mood\":\"势不可挡\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep10-s04', 'fe-dark-dragon', 10, 20, 1, 'wide', '环境展示', '暗黑神殿内部——黑色玄武岩构建的巨大空间。无数蜡烛提供诡异照明。地面绘有召唤法阵。中央祭坛上方悬挂着空间裂缝。', NULL, NULL, 'dark-shrine', NULL, 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/846d4c26d2ba465f8dab82eceb955205.png', NULL, NULL, 'pending', '{\"mood\":\"终极邪恶场所\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep10-s05', 'fe-dark-dragon', 10, 20, 2, 'low-angle', '仰拍', '卡涅夫站在祭坛上——瘦高身躯裹在黑色长袍中兜帽遮脸，眼中闪烁红光。手中黑水晶法杖散发的黑暗能量形成一道屏障。', NULL, 'char-ganev', 'dark-shrine', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/6fd41d988859465abb2edc162110d8ed.png', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/846d4c26d2ba465f8dab82eceb955205.png', NULL, NULL, 'pending', '{\"mood\":\"BOSS登场\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep10-s06', 'fe-dark-dragon', 10, 20, 3, 'medium', '正面冲突', '卡涅夫释放暗黑魔法攻击。马尔斯用法尔西昂格挡但被震退——普通攻击无法穿透屏障。', NULL, 'char-ganev', 'dark-shrine', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/6fd41d988859465abb2edc162110d8ed.png', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/846d4c26d2ba465f8dab82eceb955205.png', NULL, NULL, 'pending', '{\"mood\":\"陷入劣势\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep10-s07', 'fe-dark-dragon', 10, 20, 4, 'close-up', '特写觉醒', '马尔斯闭上眼回忆哥多的教诲。当他再次睁眼时瞳孔中的星光暴涨——右手释放出星光魔法！', NULL, 'char-mars', 'dark-shrine', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/07c898cace394c39aca262a10dbb1766.jpeg', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/846d4c26d2ba465f8dab82eceb955205.png', NULL, NULL, 'pending', '{\"mood\":\"关键时刻\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep10-s08', 'fe-dark-dragon', 10, 20, 5, 'wide', '特效爆炸', '星光击中卡涅夫的暗黑屏障——屏障像玻璃一样碎裂！卡涅夫发出惊恐的尖叫。', NULL, 'char-ganev', 'dark-shrine', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/6fd41d988859465abb2edc162110d8ed.png', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/846d4c26d2ba465f8dab82eceb955205.png', NULL, NULL, 'pending', '{\"mood\":\"逆转胜利\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep10-s09', 'fe-dark-dragon', 10, 21, 1, 'medium', '缓慢推进', '暗黑神殿最深处的一个囚室。艾莉丝蜷缩在角落——银白发凌乱苍白的脸但眼中还有希望。', NULL, 'char-elis', 'dark-shrine', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/4d80bc2c412d475cb118da1afe3196ae.png', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/846d4c26d2ba465f8dab82eceb955205.png', NULL, NULL, 'pending', '{\"mood\":\"姐弟重逢前奏\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep10-s10', 'fe-dark-dragon', 10, 21, 2, 'close-up', '情感特写', '马尔斯冲进来跪在艾莉斯面前。姐姐看到弟弟的那一刻泪水夺眶而出。', '艾莉斯：马尔斯……真的是你……我的弟弟长大了……', 'char-elis', 'dark-shrine', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/4d80bc2c412d475cb118da1afe3196ae.png', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/846d4c26d2ba465f8dab82eceb955205.png', NULL, NULL, 'pending', '{\"mood\":\"催泪重逢\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep10-s11', 'fe-dark-dragon', 10, 21, 3, 'medium', '拥抱镜头', '姐弟拥抱在一起。背景中其他伙伴默默转身给他们留出空间。', NULL, 'char-mars', 'dark-shrine', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/07c898cace394c39aca262a10dbb1766.jpeg', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/846d4c26d2ba465f8dab82eceb955205.png', NULL, NULL, 'pending', '{\"mood\":\"温情时刻\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep10-s12', 'fe-dark-dragon', 10, 21, 4, 'wide', '极致广角低机位', '暗黑神殿最深处崩裂——巨大的暗黑龙梅迪乌斯从地下升起！体型遮天蔽日，黑色鳞片覆盖全身，红色眼睛如同深渊，漆黑双翼展开几乎填满整个画面。', NULL, 'char-medius', 'dark-shrine', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/3365f57815db422dbb4b01527e1b7c5e.png', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/846d4c26d2ba465f8dab82eceb955205.png', NULL, NULL, 'pending', '{\"mood\":\"终极BOSS降临\",\"scale\":\"史诗级\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep10-s13', 'fe-dark-dragon', 10, 21, 5, 'extreme-wide', '远景对峙', '马尔斯独自面对巨龙的渺小身影。法尔西昂在他手中光芒越来越亮。火焰纹章在他胸口发出共鸣之光。', NULL, 'char-mars', 'dark-shrine', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/07c898cace394c39aca262a10dbb1766.jpeg', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/846d4c26d2ba465f8dab82eceb955205.png', NULL, NULL, 'pending', '{\"mood\":\"宿命对决\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep10-s14', 'fe-dark-dragon', 10, 21, 6, 'wide', '快速剪辑', '史诗级战斗——梅迪乌斯的暗黑吐息 vs 法尔西昂的圣光斩击。每一次碰撞都引发能量冲击波摧毁周围的建筑结构。', NULL, 'char-medius', 'dark-shrine', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/3365f57815db422dbb4b01527e1b7c5e.png', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/846d4c26d2ba465f8dab82eceb955205.png', NULL, NULL, 'pending', '{\"mood\":\"终极激战\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep10-s15', 'fe-dark-dragon', 10, 21, 7, 'slow-motion', '慢动作决胜', '马尔斯跃起到半空——法尔西昂吸收了火焰纹章的全部力量爆发出前所未有的光辉。一击刺入梅迪乌斯的心脏位置！', NULL, 'char-mars', 'dark-shrine', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/07c898cace394c39aca262a10dbb1766.jpeg', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/846d4c26d2ba465f8dab82eceb955205.png', NULL, NULL, 'pending', '{\"mood\":\"终结一击\",\"key_moment\":\"全剧高潮\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep10-s16', 'fe-dark-dragon', 10, 21, 8, 'wide', '延时效果', '梅迪乌斯发出最后的咆哮后身体开始崩解——化为无数黑色的碎片消散在空气中。暗黑神殿开始坍塌但光芒从裂缝中涌入。', NULL, 'char-medius', 'dark-shrine', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/3365f57815db422dbb4b01527e1b7c5e.png', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/846d4c26d2ba465f8dab82eceb955205.png', NULL, NULL, 'pending', '{\"mood\":\"BOSS消亡\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep10-s17', 'fe-dark-dragon', 10, 22, 1, 'wide', '日出航拍', '时间跳跃后的画面——清晨阳光下的阿利提亚城楼顶部。石质垛口上站着两个身影眺望远方苏醒的城市。', NULL, NULL, 'altea-city-wall', NULL, 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/2885d4ee1365451db4446c137a4dce96.png', NULL, NULL, 'pending', '{\"mood\":\"和平到来\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep10-s18', 'fe-dark-dragon', 10, 22, 2, 'medium', '侧面中景', '马尔斯和希达并肩站着。马尔斯穿着王室礼服不再是铠甲。希达靠在他的肩头。两人的表情平静而幸福。', '希达：终于结束了……对吧？', 'char-shiida', 'altea-city-wall', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/9589d23d3ca64315a7e79e1388ceb7eb.jpeg', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/2885d4ee1365451db4446c137a4dce96.png', NULL, NULL, 'pending', '{\"mood\":\"温情结局\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep10-s19', 'fe-dark-dragon', 10, 22, 3, 'medium', '正面对话', '马尔斯转头看向希达微笑。远处城市的钟声响起——新纪元的开始。', '马尔斯：不……这只是新的开始。（看向远方的大陆）还有很多事情要做呢。', 'char-mars', 'altea-city-wall', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/07c898cace394c39aca262a10dbb1766.jpeg', 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/2885d4ee1365451db4446c137a4dce96.png', NULL, NULL, 'pending', '{\"mood\":\"展望未来\"}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
INSERT INTO `storyboards` VALUES ('sb-ep10-s20', 'fe-dark-dragon', 10, 22, 4, 'wide', '最终拉升后拉', '镜头缓缓升高越过城楼——展现整个阿卡奈亚大陆的鸟瞰图。各国旗帜在风中飘扬，田野绿意盎然，城市炊烟袅袅。画面渐变为标题字幕。', NULL, NULL, 'altea-city-wall', NULL, 'https://avater2025.oss-cn-chengdu.aliyuncs.com/drama-assets/2026/04/20/2885d4ee1365451db4446c137a4dce96.png', NULL, NULL, 'pending', '{\"mood\":\"史诗结局\",\"series_finale\":true}', 0, '2026-04-16 21:59:47', '2026-04-20 17:16:50');
