  `updated_at` datetime(0) DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0),
  `preview_audio_url` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '试听音频URL（OSS归档）',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_drama_id`(`drama_id`) USING BTREE,
  CONSTRAINT `characters_ibfk_1` FOREIGN KEY (`drama_id`) REFERENCES `dramas` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
