DROP TABLE IF EXISTS `dramas`;
CREATE TABLE `dramas`  (
  `id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'UUID',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '剧集标题',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '剧集描述',
  `cover_image` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '封面图URL',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT 'draft' COMMENT '状态: draft/in_progress/completed',
  `total_episodes` int(0) DEFAULT 0 COMMENT '总集数',
  `created_episodes` int(0) DEFAULT 0 COMMENT '已生成集数',
  `settings` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT 'JSON配置',
  `deleted` tinyint(1) DEFAULT 0 COMMENT '逻辑删除: 0正常/1已删',
