DROP TABLE IF EXISTS `episode_exports`;
CREATE TABLE `episode_exports`  (
  `id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '导出ID',
  `drama_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '剧集ID',
  `episode_number` int(0) NOT NULL COMMENT '集数',
  `export_url` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '导出视频URL',
  `duration` float DEFAULT NULL COMMENT '视频时长(秒)',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT 'processing' COMMENT '状态: processing/completed/failed',
  `shot_count` int(0) DEFAULT 0 COMMENT '分镜数量',
