  `dialogue` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '台词',
  `character_id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '角色ID（主角色，兼容旧数据）',
  `scene_id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '场景ID',
